@dataclass(frozen=True)
class StateVector:
    x_au: float
    y_au: float
    z_au: float
    vx_au_d: float
    vy_au_d: float
    vz_au_d: float

    @property
    def radius_au(self) -> float:
        return math.sqrt(self.x_au**2 + self.y_au**2 + self.z_au**2)


