@dataclass(frozen=True)
class SolarScene:
    schema: str
    app_version: str
    epoch_utc: str
    reference_frame: str
    reference_plane: str
    physical_units: str
    display_projection: str
    max_reference_radius_au: float
    source: str
    authority: str
    renderer_rule: str
    orbit_semantics: str
    entities: tuple[SolarEntity, ...]
    orbit_tracks: tuple[OrbitTrack, ...]
    local_body_orbit_tracks: tuple[LocalBodyOrbitTrack, ...]
    infrastructure_orbit_tracks: tuple[InfrastructureOrbitTrack, ...]
    context_layers: tuple[ContextLayer, ...]
    atlas: dict[str, dict]
    catalog: dict[str, dict]

    def to_json_dict(self) -> dict:
        d = asdict(self)
        for e in d["entities"]:
            e["display_xyz"] = list(e["display_xyz"])
        for track in d["orbit_tracks"]:
            track["physical_points_au"] = [list(p) for p in track["physical_points_au"]]
            track["display_points"] = [list(p) for p in track["display_points"]]
        for track in d["local_body_orbit_tracks"]:
            track["physical_points_parent_km"] = [list(p) for p in track["physical_points_parent_km"]]
        for track in d["infrastructure_orbit_tracks"]:
            track["physical_points_parent_km"] = [list(p) for p in track["physical_points_parent_km"]]
        for layer in d["context_layers"]:
            layer["physical_points_au"] = [list(p) for p in layer["physical_points_au"]]
            layer["display_points"] = [list(p) for p in layer["display_points"]]
        return d


def parse_epoch(value: str) -> datetime:
    try:
        dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError as exc:
        raise SolarSceneError(f"invalid ISO-8601 epoch: {value}") from exc
    if dt.tzinfo is None:
        raise SolarSceneError("epoch must include timezone / Z")
    return dt.astimezone(timezone.utc)


def utc_iso(dt: datetime) -> str:
    return dt.astimezone(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")


def horizons_params(command: str, epoch: datetime) -> dict[str, str]:
    stop = epoch + timedelta(minutes=2)
    return {
        "format": "json",
        "COMMAND": f"'{command}'",
        "OBJ_DATA": "'NO'",
        "MAKE_EPHEM": "'YES'",
        "EPHEM_TYPE": "'VECTORS'",
        "CENTER": "'500@10'",
        "START_TIME": f"'{epoch.strftime('%Y-%m-%d %H:%M')}'",
        "STOP_TIME": f"'{stop.strftime('%Y-%m-%d %H:%M')}'",
        "STEP_SIZE": "'1m'",
        "REF_PLANE": "'ECLIPTIC'",
        "REF_SYSTEM": "'J2000'",
        "VEC_CORR": "'NONE'",
        "VEC_TABLE": "'2'",
        "OUT_UNITS": "'AU-D'",
        "CSV_FORMAT": "'YES'",
    }


def parse_horizons_first_vector(result: str) -> StateVector:
    if "$$SOE" not in result or "$$EOE" not in result:
        raise SolarSceneError("Horizons response has no vector block")
    block = result.split("$$SOE", 1)[1].split("$$EOE", 1)[0].strip()
    for line in block.splitlines():
        if not line.strip():
            continue
        vals = [v.strip() for v in next(csv.reader(io.StringIO(line)))]
        if len(vals) < 8:
            continue
        try:
            nums = [float(vals[i]) for i in range(2, 8)]
        except ValueError:
            continue
        if not all(math.isfinite(v) for v in nums):
            raise SolarSceneError("non-finite Horizons vector")
        return StateVector(*nums)
    raise SolarSceneError("Horizons vector block was empty")


def fetch_vector(command: str, epoch: datetime, timeout: float = 8.0) -> StateVector:
    url = HORIZONS_URL + "?" + urlencode(horizons_params(command, epoch))
    req = Request(url, headers={"User-Agent": f"LOOM-Solar-GIS/{APP_VERSION}"})
    try:
        with urlopen(req, timeout=timeout) as resp:
            payload = json.loads(resp.read().decode("utf-8"))
    except Exception as exc:
        raise SolarSceneError(f"Horizons request failed for COMMAND={command}: {exc}") from exc
    if payload.get("error"):
        raise SolarSceneError(str(payload["error"]))
    return parse_horizons_first_vector(payload.get("result", ""))

def fetch_vector_centered(command: str, center_command: str, epoch: datetime, timeout: float = 8.0) -> StateVector:
    p=horizons_params(command,epoch); p["CENTER"]=f"'500@{center_command}'"
    url=HORIZONS_URL+"?"+urlencode(p); req=Request(url,headers={"User-Agent":f"LOOM-Solar-GIS/{APP_VERSION}"})
    try:
        with urlopen(req,timeout=timeout) as resp: payload=json.loads(resp.read().decode("utf-8"))
    except Exception as exc: raise SolarSceneError(f"Horizons centered request failed for COMMAND={command}: {exc}") from exc
    if payload.get("error"): raise SolarSceneError(str(payload["error"]))
    return parse_horizons_first_vector(payload.get("result",""))

def add_states(a: StateVector,b: StateVector) -> StateVector:
    return StateVector(a.x_au+b.x_au,a.y_au+b.y_au,a.z_au+b.z_au,a.vx_au_d+b.vx_au_d,a.vy_au_d+b.vy_au_d,a.vz_au_d+b.vz_au_d)

def circular_local_fallback(command: str,a_km: float,period_days: float,epoch: datetime) -> StateVector:
    r=a_km/AU_KM; phase=((sum(ord(c) for c in command)*0.173)+(epoch.timestamp()/86400.0)*(2*math.pi/period_days))%(2*math.pi)
    w=2*math.pi/period_days
    return StateVector(r*math.cos(phase),r*math.sin(phase),0.0,-r*w*math.sin(phase),r*w*math.cos(phase),0.0)


def nav_radial_display_xyz(x: float, y: float, z: float,
                           max_radius_au: float = MAX_REFERENCE_RADIUS_AU) -> tuple[float, float, float]:
    r = math.sqrt(x*x + y*y + z*z)
    if r <= 0:
        return (0.0, 0.0, 0.0)
    mapped = math.asinh(2.2 * r) / math.asinh(2.2 * max_radius_au)
    mapped = max(0.0, min(mapped, 1.08))
    s = mapped / r
    return (x*s, y*s, z*s)


def nav_radial_display(state: StateVector,
                       max_radius_au: float = MAX_REFERENCE_RADIUS_AU) -> tuple[float, float, float]:
    """Non-linear visual radius; preserves the physical 3D direction exactly."""
    return nav_radial_display_xyz(state.x_au, state.y_au, state.z_au, max_radius_au)


def _cross(a, b):
    return (
        a[1]*b[2] - a[2]*b[1],
        a[2]*b[0] - a[0]*b[2],
        a[0]*b[1] - a[1]*b[0],
    )


def _dot(a, b):
    return a[0]*b[0] + a[1]*b[1] + a[2]*b[2]


def _norm(a):
    return math.sqrt(_dot(a, a))


def _scale(a, s):
    return (a[0]*s, a[1]*s, a[2]*s)


def _sub(a, b):
    return (a[0]-b[0], a[1]-b[1], a[2]-b[2])


def osculating_orbit_from_state(state: StateVector, samples: int = 192) -> tuple[float, float, tuple[tuple[float, float, float], ...]]:
    """Return (eccentricity, semimajor_axis_au, physical orbit points).

    Reconstructs the instantaneous heliocentric two-body osculating ellipse from the
    provided state vector. This is a display/analysis derivative of JPL state, not a
    time-propagated ephemeris.
    """
    if samples < 32:
        raise SolarSceneError("orbit samples must be >= 32")
    rvec = (state.x_au, state.y_au, state.z_au)
    vvec = (state.vx_au_d, state.vy_au_d, state.vz_au_d)
    r = _norm(rvec)
    v = _norm(vvec)
    if r <= 0 or v <= 0:
        raise SolarSceneError("cannot derive orbit from zero state")
    hvec = _cross(rvec, vvec)
    h = _norm(hvec)
    if h <= 1e-14:
        raise SolarSceneError("degenerate angular momentum")
    vxh = _cross(vvec, hvec)
    evec = _sub(_scale(vxh, 1.0/MU_SUN_AU3_D2), _scale(rvec, 1.0/r))
    e = _norm(evec)
    energy = 0.5*v*v - MU_SUN_AU3_D2/r
    if not math.isfinite(e) or not math.isfinite(energy) or energy >= 0 or e >= 1.0:
        raise SolarSceneError(f"non-elliptic osculating state: e={e:.6g}, energy={energy:.6g}")
    a = -MU_SUN_AU3_D2/(2.0*energy)
    p = h*h/MU_SUN_AU3_D2
    hhat = _scale(hvec, 1.0/h)
    if e > 1e-10:
        phat = _scale(evec, 1.0/e)
    else:
        phat = _scale(rvec, 1.0/r)
    qhat = _cross(hhat, phat)
    qn = _norm(qhat)
    if qn <= 1e-14:
        raise SolarSceneError("degenerate orbit basis")
    qhat = _scale(qhat, 1.0/qn)
    points = []
    for i in range(samples + 1):
        nu = 2.0*math.pi*i/samples
        denom = 1.0 + e*math.cos(nu)
        rr = p/denom
        c, s = math.cos(nu), math.sin(nu)
        pos = (
            rr*(c*phat[0] + s*qhat[0]),
            rr*(c*phat[1] + s*qhat[1]),
            rr*(c*phat[2] + s*qhat[2]),
        )
        points.append(pos)
    return e, a, tuple(points)



def local_osculating_orbit_from_state(state: StateVector, gm_km3_s2: float, samples: int = 160) -> tuple[float, float, tuple[tuple[float, float, float], ...]]:
    """Parent-centric instantaneous two-body osculating orbit in physical km.

    The state is already supplied by the backend ephemeris/fallback layer. This
    keeps all orbital inference out of the browser: the client only projects the
    sampled XYZ geometry supplied here.
    """
    if samples < 32:
        raise SolarSceneError("local orbit samples must be >= 32")
    mu=float(gm_km3_s2)
    if not math.isfinite(mu) or mu <= 0:
        raise SolarSceneError("invalid parent GM for local orbit")
    rvec=(state.x_au*AU_KM,state.y_au*AU_KM,state.z_au*AU_KM)
    vvec=(state.vx_au_d*AU_KM/86400.0,state.vy_au_d*AU_KM/86400.0,state.vz_au_d*AU_KM/86400.0)
    r=_norm(rvec); v=_norm(vvec)
    if r <= 0 or v <= 0:
        raise SolarSceneError("cannot derive local orbit from zero state")
    hvec=_cross(rvec,vvec); h=_norm(hvec)
    if h <= 1e-12:
        raise SolarSceneError("degenerate local angular momentum")
    evec=_sub(_scale(_cross(vvec,hvec),1.0/mu),_scale(rvec,1.0/r))
    e=_norm(evec)
    energy=0.5*v*v-mu/r
    if not math.isfinite(e) or not math.isfinite(energy) or energy >= 0 or e >= 1.0:
        raise SolarSceneError(f"non-elliptic local osculating state: e={e:.6g}, energy={energy:.6g}")
    a=-mu/(2.0*energy); p=h*h/mu
    hhat=_scale(hvec,1.0/h)
    phat=_scale(evec,1.0/e) if e > 1e-10 else _scale(rvec,1.0/r)
    qhat=_cross(hhat,phat); qn=_norm(qhat)
    if qn <= 1e-12:
        raise SolarSceneError("degenerate local orbit basis")
    qhat=_scale(qhat,1.0/qn)
    points=[]
    for i in range(samples+1):
        nu=2.0*math.pi*i/samples; denom=1.0+e*math.cos(nu); rr=p/denom
        c,s=math.cos(nu),math.sin(nu)
        points.append((rr*(c*phat[0]+s*qhat[0]),rr*(c*phat[1]+s*qhat[1]),rr*(c*phat[2]+s*qhat[2])))
    return e,a,tuple(points)

def _radical_inverse(n: int, base: int) -> float:
    inv = 1.0/base
    f = inv
    x = 0.0
    while n:
        n, digit = divmod(n, base)
        x += digit*f
        f *= inv
    return x


def build_main_belt_context(count: int = 900) -> ContextLayer:
    """Build a deterministic, non-catalog main-belt context cloud.

    Radial envelope is approximately 2.1–3.3 AU. A few broad Kirkwood-style sparse
    zones are represented for visual structure, but no point claims individual-object
    identity or exact ephemeris position.
    """
    physical_pts: list[tuple[float, float, float]] = []
    i = 1
    while len(physical_pts) < count and i < count*4:
        u = _radical_inverse(i, 2)
        v = _radical_inverse(i, 3)
        w = _radical_inverse(i, 5)
        node_u = _radical_inverse(i, 7)
        r = 2.10 + 1.20*u
        # Broad visual de-emphasis around major resonance gaps. Deterministic rejection.
        gap = min(abs(r-2.50)/0.035, abs(r-2.82)/0.030, abs(r-2.96)/0.025)
        if gap < 1.0 and _radical_inverse(i, 11) < (1.0-gap)*0.78:
            i += 1
            continue
        theta = 2.0*math.pi*v
        # Most main-belt objects are near the ecliptic, while still producing visible thickness.
        inc = (w-0.5)*0.24
        node = 2.0*math.pi*node_u
        x0, y0 = r*math.cos(theta), r*math.sin(theta)
        # Rotate a circular belt point by inclination about a varying line of nodes.
        cn, sn = math.cos(node), math.sin(node)
        ci, si = math.cos(inc), math.sin(inc)
        xr = cn*x0 + sn*y0
        yr = -sn*x0 + cn*y0
        yr2, zr2 = yr*ci, yr*si
        x = cn*xr - sn*yr2
        y = sn*xr + cn*yr2
        z = zr2
        physical_pts.append((x, y, z))
        i += 1
    return ContextLayer(
        layer_id="MAIN_BELT_CONTEXT",
        name="Main Asteroid Belt",
        layer_class="CARTOGRAPHIC_DENSITY_CONTEXT",
        authority="NON_AUTHORITATIVE_OBJECT_CATALOG",
        provenance="DETERMINISTIC_2.1_TO_3.3_AU_CONTEXT_WITH_VISUAL_RESONANCE_GAPS",
        physical_points_au=tuple(physical_pts),
        display_points=tuple(nav_radial_display_xyz(*p) for p in physical_pts),
    )


def validate_scene(scene: SolarScene) -> None:
    if scene.schema != SCENE_SCHEMA:
        raise SolarSceneError("scene schema mismatch")
    if scene.reference_frame != "J2000" or scene.reference_plane != "ECLIPTIC":
        raise SolarSceneError("unexpected reference frame")
    ids = [e.entity_id for e in scene.entities]
    if ids[:len(EXPECTED_IDS)] != EXPECTED_IDS:
        raise SolarSceneError(f"celestial entity order/id mismatch: {ids[:len(EXPECTED_IDS)]}")
    if len(ids)!=len(set(ids)):
        raise SolarSceneError("duplicate scene entity ids")
    orbit_ids = [o.entity_id for o in scene.orbit_tracks]
    if orbit_ids != [x[0] for x in OBJECTS]:
        raise SolarSceneError(f"orbit order/id mismatch: {orbit_ids}")
    for entity in scene.entities:
        values = list(asdict(entity.state).values()) + list(entity.display_xyz)
        if not all(math.isfinite(float(x)) for x in values):
            raise SolarSceneError(f"non-finite entity state: {entity.entity_id}")
        if entity.entity_id != "SOL" and entity.state.radius_au <= 0:
            raise SolarSceneError(f"non-positive radius: {entity.entity_id}")
    for orbit in scene.orbit_tracks:
        if not (0 <= orbit.eccentricity < 1):
            raise SolarSceneError(f"invalid eccentricity: {orbit.entity_id}")
        if orbit.semimajor_axis_au <= 0 or len(orbit.display_points) < 33 or len(orbit.physical_points_au) != len(orbit.display_points):
            raise SolarSceneError(f"invalid orbit: {orbit.entity_id}")
        if not all(math.isfinite(c) for p in orbit.display_points for c in p):
            raise SolarSceneError(f"non-finite orbit display geometry: {orbit.entity_id}")
        if not all(math.isfinite(c) for p in orbit.physical_points_au for c in p):
            raise SolarSceneError(f"non-finite orbit physical geometry: {orbit.entity_id}")
    for orbit in scene.local_body_orbit_tracks:
        if orbit.parent_entity_id not in ids or orbit.entity_id not in ids:
            raise SolarSceneError(f"local orbit entity/parent missing: {orbit.entity_id}")
        if not (0 <= orbit.eccentricity < 1) or orbit.semimajor_axis_km <= 0 or len(orbit.physical_points_parent_km) < 33:
            raise SolarSceneError(f"invalid local body orbit: {orbit.entity_id}")
        if not all(math.isfinite(c) for p in orbit.physical_points_parent_km for c in p):
            raise SolarSceneError(f"non-finite local body orbit: {orbit.entity_id}")
    if not scene.context_layers or scene.context_layers[0].layer_id != "MAIN_BELT_CONTEXT":
        raise SolarSceneError("main belt context missing")
    layer = scene.context_layers[0]
    if len(layer.physical_points_au) != len(layer.display_points):
        raise SolarSceneError("main belt physical/display geometry mismatch")


