class CivStateStore:
    """Strict, read-only adapter for the adjacent locked CIVSTATE database."""

    REQUIRED_OBJECTS = {
        "civ_meta", "civ_subject", "civ_infrastructure_state",
        "civ_transport_flow", "civ_runtime_place_context",
        "v_graph_nodes", "v_graph_display_edges", "v_graph_link_catalog",
        "v_graph_civstate_influence_edges", "v_graph_civstate_actor_exposure",
    }

    def __init__(self, path: str | Path):
        self.path = str(Path(path).expanduser().resolve())
        p = Path(self.path)
        if not p.is_file():
            raise FileNotFoundError(f"CIVSTATE database not found: {p}")
        digest = hashlib.sha256(p.read_bytes()).hexdigest()
        self.sha256 = digest
        self.reference_sha256 = REFERENCE_CIVSTATE_SHA256
        self.reference_hash_match = (digest == REFERENCE_CIVSTATE_SHA256)
        self.conn = sqlite3.connect(f"file:{p.as_posix()}?mode=ro", uri=True)
        self.conn.row_factory = sqlite3.Row
        self.conn.execute("PRAGMA query_only=ON")
        self._validate()

    def _validate(self) -> None:
        if str(self.conn.execute("PRAGMA quick_check").fetchone()[0]).lower() != "ok":
            raise sqlite3.DatabaseError("CIVSTATE quick_check failed")
        objects = {r[0] for r in self.conn.execute(
            "SELECT name FROM sqlite_master WHERE type IN ('table','view')"
        )}
        missing = sorted(self.REQUIRED_OBJECTS - objects)
        if missing:
            raise RuntimeError("CIVSTATE required objects missing: " + ", ".join(missing))
        meta = dict(self.conn.execute("SELECT key,value FROM civ_meta"))
        if meta.get("schema_name") != "LOOM_2226_CIVSTATE" or meta.get("schema_version") != LOCKED_CIVSTATE_SCHEMA:
            raise RuntimeError(f"Unsupported CIVSTATE schema: {meta}")
        self.meta = meta

    def close(self) -> None:
        self.conn.close()

    def info(self) -> dict:
        def count(name: str) -> int:
            return int(self.conn.execute(f'SELECT COUNT(*) FROM "{name}"').fetchone()[0])
        return {
            "path": self.path, "schema_name": self.meta["schema_name"],
            "schema_version": self.meta["schema_version"], "sha256": self.sha256,
            "reference_sha256": self.reference_sha256,
            "reference_hash_match": self.reference_hash_match,
            "validation_mode": "SCHEMA+OBJECTS+SQLITE_INTEGRITY",
            "subjects": count("civ_subject"),
            "infrastructure_states": count("civ_infrastructure_state"),
            "transport_flows": count("civ_transport_flow"),
            "runtime_places": count("civ_runtime_place_context"),
            "graph_nodes": count("v_graph_nodes"),
            "graph_display_edges": count("v_graph_display_edges"),
            "graph_influence_edges": count("v_graph_civstate_influence_edges"),
            "graph_actor_exposure": count("v_graph_civstate_actor_exposure"),
        }

    def _subject(self, entity_id: str) -> sqlite3.Row | None:
        return self.conn.execute(
            "SELECT * FROM civ_subject WHERE navigator_entity_id=? AND aggregation_class='NAVIGATOR_ENTITY' LIMIT 1",
            (entity_id,),
        ).fetchone()

    def entity_context(self, entity_id: str) -> dict | None:
        subject = self._subject(entity_id)
        if not subject:
            return None
        sid = subject["subject_id"]
        if subject["subject_class"] == "INFRASTRUCTURE":
            node_ids = [r[0] for r in self.conn.execute(
                "SELECT subject_id FROM civ_subject WHERE navigator_node_id=? AND aggregation_class='INFRASTRUCTURE'",
                (entity_id,),
            )]
        else:
            node_ids = [r[0] for r in self.conn.execute("""
                WITH RECURSIVE tree(subject_id) AS (
                    SELECT ? UNION ALL
                    SELECT s.subject_id FROM civ_subject s JOIN tree t ON s.parent_subject_id=t.subject_id
                    WHERE s.aggregation_class='NAVIGATOR_ENTITY'
                )
                SELECT n.subject_id FROM civ_subject n
                WHERE n.aggregation_class='INFRASTRUCTURE'
                  AND n.spatial_subject_id IN (SELECT subject_id FROM tree)
                ORDER BY n.navigator_node_id
            """, (sid,))]
        if not node_ids:
            return {"subject": dict(subject), "nodes": [], "aggregate": None, "flows": None}
        marks = ",".join("?" for _ in node_ids)
        nodes = [dict(r) for r in self.conn.execute(f"""
            SELECT r.*, i.capital_stock,i.replacement_value,i.annual_operating_cost,
                   i.power_peak_mw,i.habitable_capacity,i.industrial_capacity_index,
                   i.passenger_movements_year,i.ship_calls_year,i.berths_equivalent,i.utilization,
                   i.derivation_id infrastructure_derivation_id
            FROM civ_runtime_place_context r
            JOIN civ_infrastructure_state i ON i.node_subject_id=r.subject_id AND i.year=2226
            WHERE r.subject_id IN ({marks}) ORDER BY r.navigator_node_id
        """, node_ids)]
        agg = dict(self.conn.execute(f"""
            SELECT COUNT(*) facility_count,
                   SUM(resident_population) resident_population,
                   SUM(transient_daily_population) transient_daily_population,
                   SUM(workforce) workforce, SUM(capital_stock) capital_stock,
                   SUM(replacement_value) replacement_value,
                   SUM(annual_value_added) annual_value_added,
                   SUM(annual_operating_cost) annual_operating_cost,
                   SUM(power_average_mw) power_average_mw, SUM(power_peak_mw) power_peak_mw,
                   SUM(habitable_capacity) habitable_capacity,
                   SUM(cargo_throughput_tonnes_year) cargo_throughput_tonnes_year,
                   SUM(passenger_movements_year) passenger_movements_year,
                   SUM(ship_calls_year) ship_calls_year,
                   CASE
                     WHEN SUM(COALESCE(habitable_capacity,0))>0 THEN
                       SUM(COALESCE(resident_population,0)+COALESCE(transient_daily_population,0))
                       / SUM(COALESCE(habitable_capacity,0))
                     ELSE NULL
                   END utilization,
                   MAX(strategic_importance) strategic_importance,
                   MAX(economic_centrality) economic_centrality,
                   MAX(transport_centrality) transport_centrality
            FROM civ_infrastructure_state WHERE year=2226 AND node_subject_id IN ({marks})
        """, node_ids).fetchone())
        flow = dict(self.conn.execute(f"""
            SELECT COUNT(*) route_count,
                   SUM(passengers_year) passengers_year,
                   SUM(freight_tonnes_year) freight_tonnes_year,
                   SUM(ship_movements) ship_movements,
                   AVG(accessibility_index) accessibility_index,
                   MAX(route_importance) route_importance
            FROM civ_transport_flow WHERE year=2226
              AND (origin_subject_id IN ({marks}) OR destination_subject_id IN ({marks}))
        """, node_ids + node_ids).fetchone())

        # Richer player-facing context from existing CIVSTATE tables only.  These
        # are optional presentation reads: no new schema fields are introduced.
        objects = {r[0] for r in self.conn.execute(
            "SELECT name FROM sqlite_master WHERE type IN ('table','view')"
        )}
        demographics = None
        workforce = None
        economy = None
        sectors = []
        actors = []
        actor_facilities = []
        influence_edges = []
        provenance = {}
        connections = {"outbound": [], "inbound": []}
        if "civ_demographic_state" in objects:
            r = self.conn.execute(
                "SELECT * FROM civ_demographic_state WHERE subject_id=? AND year=2226 LIMIT 1", (sid,)
            ).fetchone()
            demographics = dict(r) if r else None
        if "civ_workforce_state" in objects:
            r = self.conn.execute(
                "SELECT * FROM civ_workforce_state WHERE subject_id=? AND year=2226 AND sector_id='ALL' LIMIT 1", (sid,)
            ).fetchone()
            workforce = dict(r) if r else None
        if "civ_economic_state" in objects:
            r = self.conn.execute(
                "SELECT * FROM civ_economic_state WHERE subject_id=? AND year=2226 LIMIT 1", (sid,)
            ).fetchone()
            economy = dict(r) if r else None
        if "civ_sector_state" in objects and "civ_sector" in objects:
            sectors = [dict(r) for r in self.conn.execute("""
                SELECT ss.*, s.display_name sector_name, s.sort_order
                FROM civ_sector_state ss JOIN civ_sector s ON s.sector_id=ss.sector_id
                WHERE ss.subject_id=? AND ss.year=2226
                ORDER BY COALESCE(ss.value_added,0) DESC, s.sort_order, ss.sector_id
            """, (sid,)).fetchall()]
        if "civ_actor_exposure" in objects:
            actors = [dict(r) for r in self.conn.execute(f"""
                SELECT ae.actor_subject_id, a.display_name actor_name, a.iso3,
                       MAX(COALESCE(ae.control_weight,0)) control_weight,
                       MAX(COALESCE(ae.service_dependency_weight,0)) service_dependency_weight,
                       MAX(ae.derivation_id) derivation_id
                FROM civ_actor_exposure ae
                JOIN civ_subject a ON a.subject_id=ae.actor_subject_id
                WHERE ae.year=2226 AND ae.geography_subject_id IN ({marks})
                GROUP BY ae.actor_subject_id,a.display_name,a.iso3
                ORDER BY CASE WHEN MAX(COALESCE(ae.control_weight,0)) >= MAX(COALESCE(ae.service_dependency_weight,0))
                              THEN MAX(COALESCE(ae.control_weight,0)) ELSE MAX(COALESCE(ae.service_dependency_weight,0)) END DESC,
                         a.display_name
            """, node_ids).fetchall()]


        if "civ_actor_exposure" in objects:
            actor_facilities = [dict(r) for r in self.conn.execute(f"""
                SELECT ae.actor_subject_id, a.display_name actor_name, a.iso3,
                       ae.geography_subject_id node_subject_id,
                       n.navigator_node_id, n.display_name node_name,
                       MAX(COALESCE(ae.control_weight,0)) control_weight,
                       MAX(COALESCE(ae.service_dependency_weight,0)) service_dependency_weight
                FROM civ_actor_exposure ae
                JOIN civ_subject a ON a.subject_id=ae.actor_subject_id
                JOIN civ_subject n ON n.subject_id=ae.geography_subject_id
                WHERE ae.year=2226 AND ae.geography_subject_id IN ({marks})
                GROUP BY ae.actor_subject_id,a.display_name,a.iso3,
                         ae.geography_subject_id,n.navigator_node_id,n.display_name
                ORDER BY a.display_name,n.display_name
            """, node_ids).fetchall()]

        if "civ_influence_edge" in objects:
            influence_edges = [dict(r) for r in self.conn.execute(f"""
                SELECT ie.subject_id node_subject_id,
                       n.navigator_node_id, n.display_name node_name,
                       ie.actor_subject_id,
                       a.display_name actor_name, a.subject_class actor_class, a.iso3,
                       ie.influence_domain, ie.influence_weight,
                       ie.control_class, ie.basis, ie.derivation_id
                FROM civ_influence_edge ie
                JOIN civ_subject a ON a.subject_id=ie.actor_subject_id
                JOIN civ_subject n ON n.subject_id=ie.subject_id
                WHERE ie.year=2226 AND ie.subject_id IN ({marks})
                ORDER BY ie.influence_weight DESC, a.display_name, ie.influence_domain
            """, node_ids).fetchall()]

        if "civ_derivation" in objects:
            derivation_ids = set()
            for obj in (demographics, workforce, economy):
                if obj and obj.get("derivation_id"):
                    derivation_ids.add(obj["derivation_id"])
            for n in nodes:
                if n.get("infrastructure_derivation_id"):
                    derivation_ids.add(n["infrastructure_derivation_id"])
            for a in actors:
                if a.get("derivation_id"):
                    derivation_ids.add(a["derivation_id"])
            if derivation_ids:
                dm = ",".join("?" for _ in derivation_ids)
                provenance = {r["derivation_id"]: dict(r) for r in self.conn.execute(f"""
                    SELECT derivation_id,epistemic_class,run_id,method,source_detail,
                           confidence,uncertainty_low,uncertainty_high,notes
                    FROM civ_derivation WHERE derivation_id IN ({dm})
                    ORDER BY derivation_id
                """, tuple(sorted(derivation_ids))).fetchall()}

        # Aggregate meaningful external OD links for the selected place. Internal
        # node-to-node circulation is intentionally excluded from these rankings.
        if node_ids:
            out_rows = self.conn.execute(f"""
                SELECT d.spatial_subject_id peer_spatial_subject_id,
                       COALESCE(pe.navigator_entity_id,d.navigator_entity_id) peer_entity_id,
                       COALESCE(pe.display_name,d.display_name) peer_name,
                       SUM(COALESCE(f.passengers_year,0)) passengers_year,
                       SUM(COALESCE(f.freight_tonnes_year,0)) freight_tonnes_year,
                       SUM(COALESCE(f.ship_movements,0)) ship_movements,
                       MAX(COALESCE(f.route_importance,0)) route_importance
                FROM civ_transport_flow f
                JOIN civ_subject d ON d.subject_id=f.destination_subject_id
                LEFT JOIN civ_subject pe ON pe.subject_id=d.spatial_subject_id
                WHERE f.year=2226 AND f.origin_subject_id IN ({marks})
                  AND f.destination_subject_id NOT IN ({marks})
                GROUP BY d.spatial_subject_id,COALESCE(pe.navigator_entity_id,d.navigator_entity_id),COALESCE(pe.display_name,d.display_name)
                ORDER BY SUM(COALESCE(f.freight_tonnes_year,0)) DESC,
                         SUM(COALESCE(f.passengers_year,0)) DESC LIMIT 8
            """, node_ids + node_ids).fetchall()
            in_rows = self.conn.execute(f"""
                SELECT o.spatial_subject_id peer_spatial_subject_id,
                       COALESCE(pe.navigator_entity_id,o.navigator_entity_id) peer_entity_id,
                       COALESCE(pe.display_name,o.display_name) peer_name,
                       SUM(COALESCE(f.passengers_year,0)) passengers_year,
                       SUM(COALESCE(f.freight_tonnes_year,0)) freight_tonnes_year,
                       SUM(COALESCE(f.ship_movements,0)) ship_movements,
                       MAX(COALESCE(f.route_importance,0)) route_importance
                FROM civ_transport_flow f
                JOIN civ_subject o ON o.subject_id=f.origin_subject_id
                LEFT JOIN civ_subject pe ON pe.subject_id=o.spatial_subject_id
                WHERE f.year=2226 AND f.destination_subject_id IN ({marks})
                  AND f.origin_subject_id NOT IN ({marks})
                GROUP BY o.spatial_subject_id,COALESCE(pe.navigator_entity_id,o.navigator_entity_id),COALESCE(pe.display_name,o.display_name)
                ORDER BY SUM(COALESCE(f.freight_tonnes_year,0)) DESC,
                         SUM(COALESCE(f.passengers_year,0)) DESC LIMIT 8
            """, node_ids + node_ids).fetchall()
            connections = {"outbound": [dict(r) for r in out_rows], "inbound": [dict(r) for r in in_rows]}
        return {"subject": dict(subject), "nodes": nodes, "aggregate": agg, "flows": flow,
                "demographics": demographics, "workforce_detail": workforce, "economy_detail": economy,
                "sectors": sectors, "actors": actors, "actor_facilities": actor_facilities,
                "influence_edges": influence_edges, "provenance": provenance,
                "connections": connections}


class SolarStore:
    """SQLite authority/cache for Solar GIS spatial state and Atlas attributes.

    Runtime rule: physical state and attributes persist here; display geometry remains
    a renderer projection derived from physical coordinates and is never authoritative.
    """

    def __init__(self, path: str | Path, civstate: CivStateStore | None = None):
        self.path = str(path)
        if self.path != ":memory:":
            Path(self.path).expanduser().resolve().parent.mkdir(parents=True, exist_ok=True)
        self.conn = sqlite3.connect(self.path)
        self.conn.row_factory = sqlite3.Row
        self.conn.execute("PRAGMA foreign_keys=ON")
        self.cache_hits = 0
        self.cache_misses = 0
        self.civstate = civstate
        self.preloaded_spatial_schema = False

    def close(self) -> None:
        self.conn.close()

    def initialize(self) -> None:
        meta_exists = self.conn.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='meta'").fetchone()
        if meta_exists:
            row = self.conn.execute("SELECT value FROM meta WHERE key='schema_version'").fetchone()
            if row and row[0] is not None:
                current_text = str(row[0])
                if current_text == "12.1-spatial":
                    required = {"entities", "states", "atlas_profiles", "infrastructure_nodes"}
                    actual = {r[0] for r in self.conn.execute("SELECT name FROM sqlite_master WHERE type='table'")}
                    missing = sorted(required - actual)
                    if missing:
                        raise RuntimeError("LOOM spatial CORE is incomplete: " + ", ".join(missing))
                    self.preloaded_spatial_schema = True
                    return
                current = int(current_text)
                target = int(DB_SCHEMA_VERSION)
                if current < target:
                    raise RuntimeError(
                        f"LOOM WORLD schema {current} is older than GIS requirement {target}. "
                        "Run LOOM_World_Model_Foundation_Migration_v1.0.py first."
                    )
                if current > target:
                    raise RuntimeError(
                        f"LOOM WORLD schema {current} is newer than this GIS runtime ({target}). "
                        "Use a matching/newer GIS build."
                    )
        self.conn.executescript("""
        CREATE TABLE IF NOT EXISTS meta (
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS entities (
            entity_id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            entity_class TEXT NOT NULL,
            parent_entity_id TEXT REFERENCES entities(entity_id),
            source_command TEXT,
            glyph_px REAL NOT NULL,
            provenance TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS states (
            entity_id TEXT NOT NULL REFERENCES entities(entity_id),
            epoch_utc TEXT NOT NULL,
            reference_frame TEXT NOT NULL,
            reference_plane TEXT NOT NULL,
            x_au REAL NOT NULL,
            y_au REAL NOT NULL,
            z_au REAL NOT NULL,
            vx_au_d REAL NOT NULL,
            vy_au_d REAL NOT NULL,
            vz_au_d REAL NOT NULL,
            source TEXT NOT NULL,
            navigation_grade INTEGER NOT NULL CHECK (navigation_grade IN (0,1)),
            PRIMARY KEY (entity_id, epoch_utc, reference_frame, reference_plane)
        );
        CREATE INDEX IF NOT EXISTS idx_states_epoch ON states(epoch_utc);

        CREATE TABLE IF NOT EXISTS orbit_snapshots (
            entity_id TEXT NOT NULL REFERENCES entities(entity_id),
            epoch_utc TEXT NOT NULL,
            model TEXT NOT NULL,
            eccentricity REAL NOT NULL,
            semimajor_axis_au REAL NOT NULL,
            provenance TEXT NOT NULL,
            navigation_grade INTEGER NOT NULL CHECK (navigation_grade IN (0,1)),
            PRIMARY KEY (entity_id, epoch_utc, model)
        );

        CREATE TABLE IF NOT EXISTS atlas_profiles (
            entity_id TEXT PRIMARY KEY REFERENCES entities(entity_id),
            title TEXT NOT NULL,
            bio TEXT,
            synth TEXT,
            status TEXT,
            summary TEXT,
            source TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS atlas_mobility (
            entity_id TEXT NOT NULL REFERENCES entities(entity_id),
            attribute_key TEXT NOT NULL,
            attribute_value TEXT NOT NULL,
            PRIMARY KEY (entity_id, attribute_key)
        );

        CREATE TABLE IF NOT EXISTS nodes (
            node_id TEXT PRIMARY KEY,
            parent_entity_id TEXT NOT NULL REFERENCES entities(entity_id),
            name TEXT,
            node_class TEXT,
            source TEXT NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_nodes_parent ON nodes(parent_entity_id);

        CREATE TABLE IF NOT EXISTS census_records (
            region TEXT PRIMARY KEY, biological TEXT, synthetic TEXT, canon_status TEXT, source TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS region_mobility (
            region TEXT PRIMARY KEY, bulk_torch TEXT, metric_traffic TEXT, loom_access TEXT, shipbuilding TEXT,
            heavy_repair TEXT, metric_overhaul TEXT, feeder_density TEXT, transport_role TEXT, source TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS infrastructure_nodes (
            node_id TEXT PRIMARY KEY, node_name TEXT NOT NULL, system TEXT, parent_body TEXT, traffic TEXT, facility_type TEXT,
            commercial_1 TEXT, commercial_2 TEXT, commercial_regime TEXT, civil_authority TEXT, administrative_authority TEXT,
            security_authority TEXT, synthetic_constituency_1 TEXT, institutional_morphology TEXT, source TEXT NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_infra_system ON infrastructure_nodes(system);
        CREATE INDEX IF NOT EXISTS idx_infra_parent ON infrastructure_nodes(parent_body);
        CREATE TABLE IF NOT EXISTS organizations (
            org_name TEXT PRIMARY KEY, org_class TEXT, region TEXT, role TEXT, boundary TEXT, source TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS regional_morphology (
            system TEXT PRIMARY KEY, political_morphology TEXT, network_form TEXT, civil_authorities TEXT,
            administrative_authorities TEXT, security_authorities TEXT, source TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS canon_source_sections (
            section_title TEXT PRIMARY KEY, content TEXT NOT NULL, source TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS entity_scopes (
            entity_id TEXT NOT NULL REFERENCES entities(entity_id), scope_value TEXT NOT NULL,
            PRIMARY KEY(entity_id,scope_value)
        );
        CREATE TABLE IF NOT EXISTS atlas_subfeatures (
            parent_entity_id TEXT NOT NULL REFERENCES entities(entity_id), name TEXT NOT NULL, intro TEXT, fields_json TEXT NOT NULL,
            source_section TEXT, source TEXT NOT NULL, PRIMARY KEY(parent_entity_id,name)
        );
        CREATE TABLE IF NOT EXISTS body_zone_census (
            row_id INTEGER PRIMARY KEY AUTOINCREMENT, system TEXT NOT NULL, body_or_network TEXT NOT NULL, zone_or_network TEXT NOT NULL,
            location_class TEXT, bio_residents REAL, synthetic_persons REAL, effective_family_gravity_g REAL, primary_role TEXT,
            bio_status TEXT, synthetic_status TEXT, biological_residence_function TEXT, family_residence_interpretation TEXT, source TEXT NOT NULL,
            UNIQUE(system,body_or_network,zone_or_network)
        );
        CREATE INDEX IF NOT EXISTS idx_body_zone_body ON body_zone_census(body_or_network);
        CREATE TABLE IF NOT EXISTS celestial_dynamics (
            entity_id TEXT PRIMARY KEY REFERENCES entities(entity_id), primary_gravity_parent_id TEXT REFERENCES entities(entity_id),
            horizons_command TEXT, parent_center_command TEXT, reference_orbit_radius_km REAL, orbital_period_days REAL,
            gm_km3_s2 REAL, mean_radius_km REAL, soi_radius_km REAL, hill_radius_km REAL, atmosphere_class TEXT,
            metadata_status TEXT NOT NULL, source TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS ephemeris_states (
            entity_id TEXT NOT NULL REFERENCES entities(entity_id), epoch_utc TEXT NOT NULL, center_entity_id TEXT, center_command TEXT,
            reference_frame TEXT NOT NULL, reference_plane TEXT NOT NULL, units TEXT NOT NULL,
            x REAL NOT NULL,y REAL NOT NULL,z REAL NOT NULL,vx REAL NOT NULL,vy REAL NOT NULL,vz REAL NOT NULL,
            source TEXT NOT NULL, ephemeris_status TEXT NOT NULL, navigation_grade INTEGER NOT NULL CHECK(navigation_grade IN(0,1)),
            PRIMARY KEY(entity_id,epoch_utc,center_entity_id,reference_frame,reference_plane)
        );
        CREATE TABLE IF NOT EXISTS provenance_sources (
            source_id TEXT PRIMARY KEY, source_class TEXT NOT NULL, citation TEXT NOT NULL, authority_status TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS transport_hubs (
            entity_id TEXT PRIMARY KEY REFERENCES entities(entity_id), traffic_class_torch TEXT, traffic_class_metric TEXT, loom_access_class TEXT,
            shipyard_class TEXT, heavy_repair TEXT, metric_overhaul TEXT, local_feeder_class TEXT, primary_transport_role TEXT,
            certification_standard_id TEXT, cert_coefficient_set_id TEXT, traffic_control_authority_id TEXT,
            roadstead_id TEXT, roadstead_status TEXT, physical_cert_model_id TEXT, od_model_id TEXT, capacity_model_id TEXT,
            model_status TEXT NOT NULL, valid_from TEXT, valid_until TEXT, provenance TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS placement_models (
            model_id TEXT PRIMARY KEY, model_class TEXT NOT NULL, version TEXT NOT NULL,
            status TEXT NOT NULL, rationale TEXT, provenance TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS entity_location_models (
            entity_id TEXT PRIMARY KEY REFERENCES entities(entity_id), model_id TEXT NOT NULL REFERENCES placement_models(model_id),
            parent_entity_id TEXT REFERENCES entities(entity_id), center_entity_id TEXT REFERENCES entities(entity_id),
            frame_family TEXT NOT NULL, geometry_kind TEXT NOT NULL, precision_class TEXT NOT NULL,
            position_authority TEXT NOT NULL, navigation_grade INTEGER NOT NULL CHECK(navigation_grade IN(0,1)),
            parameter_json TEXT NOT NULL, assumption_json TEXT NOT NULL, valid_from TEXT, valid_until TEXT
        );
        CREATE TABLE IF NOT EXISTS spatial_states (
            entity_id TEXT NOT NULL REFERENCES entities(entity_id), epoch_utc TEXT NOT NULL,
            center_entity_id TEXT, reference_frame TEXT NOT NULL, units TEXT NOT NULL,
            x_km REAL NOT NULL,y_km REAL NOT NULL,z_km REAL NOT NULL,vx_km_s REAL NOT NULL,vy_km_s REAL NOT NULL,vz_km_s REAL NOT NULL,
            state_source TEXT NOT NULL, model_id TEXT, navigation_grade INTEGER NOT NULL CHECK(navigation_grade IN(0,1)),
            validity_status TEXT NOT NULL, PRIMARY KEY(entity_id,epoch_utc,reference_frame)
        );
        CREATE INDEX IF NOT EXISTS idx_spatial_states_epoch ON spatial_states(epoch_utc);
        CREATE TABLE IF NOT EXISTS celestial_properties (
            entity_id TEXT PRIMARY KEY REFERENCES entities(entity_id), gm_km3_s2 REAL, mean_radius_km REAL,
            rotation_period_s REAL, source_id TEXT, status TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS infrastructure_physical_properties (
            entity_id TEXT PRIMARY KEY REFERENCES entities(entity_id), mass_kg REAL, characteristic_length_m REAL,
            habitable_volume_m3 REAL, rotation_model TEXT, stationkeeping_class TEXT, propulsion_class TEXT,
            source_id TEXT, status TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS world_model_migrations (
            migration_id TEXT PRIMARY KEY, applied_at TEXT NOT NULL, target_schema INTEGER NOT NULL, tool_version TEXT NOT NULL, notes TEXT
        );
        CREATE TABLE IF NOT EXISTS derivation_models (
            model_id TEXT PRIMARY KEY, domain TEXT NOT NULL, version TEXT NOT NULL, status TEXT NOT NULL,
            description TEXT NOT NULL, assumptions_json TEXT NOT NULL DEFAULT '{}', source_id TEXT REFERENCES provenance_sources(source_id), created_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS entity_authorities (
            entity_id TEXT NOT NULL REFERENCES entities(entity_id), authority_noun_id TEXT NOT NULL REFERENCES knowledge_entities(noun_id),
            authority_role TEXT NOT NULL, authority_weight REAL, precedence_rank INTEGER, scope_text TEXT, epistemic_status TEXT NOT NULL,
            source_id TEXT REFERENCES provenance_sources(source_id), source_detail TEXT, PRIMARY KEY(entity_id,authority_noun_id,authority_role)
        );
        CREATE TABLE IF NOT EXISTS entity_economic_profiles (
            entity_id TEXT PRIMARY KEY REFERENCES entities(entity_id), primary_commercial_noun_id TEXT REFERENCES knowledge_entities(noun_id),
            secondary_commercial_noun_id TEXT REFERENCES knowledge_entities(noun_id), commercial_regime TEXT, institutional_morphology TEXT,
            epistemic_status TEXT NOT NULL, source_id TEXT REFERENCES provenance_sources(source_id), source_detail TEXT
        );
        CREATE TABLE IF NOT EXISTS entity_transport_profiles (
            entity_id TEXT PRIMARY KEY REFERENCES entities(entity_id), local_traffic_class TEXT, regional_context TEXT, bulk_torch TEXT,
            metric_traffic TEXT, loom_access TEXT, shipbuilding TEXT, heavy_repair TEXT, metric_overhaul TEXT, feeder_density TEXT,
            transport_role TEXT, epistemic_status TEXT NOT NULL, source_id TEXT REFERENCES provenance_sources(source_id), source_detail TEXT
        );
        CREATE TABLE IF NOT EXISTS entity_demographic_profiles (
            entity_id TEXT PRIMARY KEY REFERENCES entities(entity_id), biological_residents REAL, synthetic_persons REAL, transient_population REAL,
            workforce_population REAL, design_capacity REAL, effective_gravity_g REAL, habitation_class TEXT, epistemic_status TEXT NOT NULL,
            source_id TEXT REFERENCES provenance_sources(source_id), derivation_model_id TEXT REFERENCES derivation_models(model_id), notes TEXT
        );
        CREATE TABLE IF NOT EXISTS infrastructure_engineering_profiles (
            entity_id TEXT PRIMARY KEY REFERENCES entities(entity_id), structural_archetype TEXT NOT NULL, characteristic_length_m REAL, width_m REAL,
            height_m REAL, diameter_m REAL, pressurized_volume_m3 REAL, habitable_volume_m3 REAL, industrial_volume_m3 REAL, storage_volume_m3 REAL,
            dry_mass_kg REAL, operating_mass_kg REAL, shielding_mass_kg REAL, rotation_model TEXT, artificial_gravity_g REAL, stationkeeping_class TEXT,
            propulsion_class TEXT, epistemic_status TEXT NOT NULL, source_id TEXT REFERENCES provenance_sources(source_id),
            derivation_model_id TEXT REFERENCES derivation_models(model_id), notes TEXT
        );
        CREATE TABLE IF NOT EXISTS infrastructure_energy_profiles (
            entity_id TEXT PRIMARY KEY REFERENCES entities(entity_id), generation_class TEXT, installed_power_mw REAL, firm_power_mw REAL, baseline_load_mw REAL,
            typical_load_mw REAL, peak_load_mw REAL, annual_energy_gwh REAL, storage_mwh REAL, emergency_endurance_h REAL, waste_heat_mw REAL,
            radiator_area_m2 REAL, rejection_temp_k REAL, epistemic_status TEXT NOT NULL, source_id TEXT REFERENCES provenance_sources(source_id),
            derivation_model_id TEXT REFERENCES derivation_models(model_id), notes TEXT
        );
        CREATE TABLE IF NOT EXISTS infrastructure_capacity_profiles (
            entity_id TEXT PRIMARY KEY REFERENCES entities(entity_id), berth_count INTEGER, simultaneous_vessel_capacity INTEGER, cargo_throughput_t_per_year REAL,
            passenger_throughput_per_year REAL, cargo_storage_t REAL, remass_storage_t REAL, repair_capacity_class TEXT, yard_capacity_t_per_year REAL,
            epistemic_status TEXT NOT NULL, source_id TEXT REFERENCES provenance_sources(source_id), derivation_model_id TEXT REFERENCES derivation_models(model_id), notes TEXT
        );
        CREATE TABLE IF NOT EXISTS transport_links (
            link_id TEXT PRIMARY KEY, origin_entity_id TEXT NOT NULL REFERENCES entities(entity_id), destination_entity_id TEXT NOT NULL REFERENCES entities(entity_id),
            mode TEXT NOT NULL, service_class TEXT, directionality TEXT NOT NULL DEFAULT 'BIDIRECTIONAL', traffic_class TEXT, freight_significance TEXT,
            passenger_significance TEXT, nominal_capacity_t_per_year REAL, typical_transit_hours REAL, operator_noun_id TEXT REFERENCES knowledge_entities(noun_id),
            epistemic_status TEXT NOT NULL, source_id TEXT REFERENCES provenance_sources(source_id), derivation_model_id TEXT REFERENCES derivation_models(model_id), notes TEXT
        );
        CREATE TABLE IF NOT EXISTS orbit_geometry_models (
            entity_id TEXT PRIMARY KEY REFERENCES entities(entity_id), orbit_family TEXT NOT NULL, parent_entity_id TEXT REFERENCES entities(entity_id),
            secondary_entity_id TEXT REFERENCES entities(entity_id), reference_frame TEXT NOT NULL, reference_plane TEXT, epoch_utc TEXT, semi_major_axis_km REAL,
            eccentricity REAL, inclination_deg REAL, raan_deg REAL, arg_periapsis_deg REAL, mean_anomaly_deg REAL, period_s REAL, amplitude_x_km REAL,
            amplitude_y_km REAL, amplitude_z_km REAL, parameter_json TEXT NOT NULL DEFAULT '{}', assumption_json TEXT NOT NULL DEFAULT '{}',
            navigation_grade INTEGER NOT NULL DEFAULT 0 CHECK(navigation_grade IN(0,1)), epistemic_status TEXT NOT NULL,
            source_id TEXT REFERENCES provenance_sources(source_id), derivation_model_id TEXT REFERENCES derivation_models(model_id), notes TEXT
        );
        CREATE TABLE IF NOT EXISTS image_assets (
            asset_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL, asset_role TEXT NOT NULL,
            prompt_version TEXT NOT NULL, prompt_hash TEXT NOT NULL, provider TEXT NOT NULL, model_id TEXT NOT NULL,
            generation_status TEXT NOT NULL, review_status TEXT NOT NULL, media_key TEXT, mime_type TEXT NOT NULL,
            width_px INTEGER, height_px INTEGER, content_hash TEXT NOT NULL, byte_length INTEGER NOT NULL,
            thumbnail_hash TEXT, thumbnail_byte_length INTEGER, created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
            is_current INTEGER NOT NULL DEFAULT 0 CHECK(is_current IN(0,1)),
            FOREIGN KEY(entity_id) REFERENCES knowledge_entities(noun_id)
        );
        CREATE INDEX IF NOT EXISTS idx_image_assets_entity ON image_assets(entity_id,asset_role,is_current);
        CREATE TABLE IF NOT EXISTS image_generation_jobs (
            job_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL, asset_role TEXT NOT NULL, prompt_hash TEXT NOT NULL,
            provider TEXT NOT NULL, model_id TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 100,
            status TEXT NOT NULL, attempt_count INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT,
            created_at TEXT NOT NULL, started_at TEXT, finished_at TEXT, error_text TEXT, provider_job_id TEXT
        );
        CREATE INDEX IF NOT EXISTS idx_image_jobs_status ON image_generation_jobs(status,priority,created_at);
        CREATE TABLE IF NOT EXISTS knowledge_entities (
            noun_id TEXT PRIMARY KEY, canonical_name TEXT NOT NULL UNIQUE, noun_class TEXT NOT NULL,
            quick_description TEXT, boundary_note TEXT, spatial_entity_id TEXT REFERENCES entities(entity_id),
            canon_status TEXT NOT NULL, source TEXT NOT NULL, source_detail TEXT
        );
        CREATE INDEX IF NOT EXISTS idx_knowledge_name ON knowledge_entities(canonical_name);
        CREATE INDEX IF NOT EXISTS idx_knowledge_spatial ON knowledge_entities(spatial_entity_id);
        CREATE TABLE IF NOT EXISTS knowledge_relationships (
            rel_id INTEGER PRIMARY KEY AUTOINCREMENT, subject_noun_id TEXT NOT NULL REFERENCES knowledge_entities(noun_id),
            predicate TEXT NOT NULL, object_noun_id TEXT NOT NULL REFERENCES knowledge_entities(noun_id),
            context_entity_id TEXT REFERENCES entities(entity_id), source_record_type TEXT NOT NULL, source_record_id TEXT,
            provenance TEXT NOT NULL, UNIQUE(subject_noun_id,predicate,object_noun_id,context_entity_id,source_record_type,source_record_id)
        );
        CREATE INDEX IF NOT EXISTS idx_krel_subject ON knowledge_relationships(subject_noun_id);
        CREATE INDEX IF NOT EXISTS idx_krel_object ON knowledge_relationships(object_noun_id);
        CREATE INDEX IF NOT EXISTS idx_krel_context ON knowledge_relationships(context_entity_id);
        """)
        entity_cols={r[1] for r in self.conn.execute("PRAGMA table_info(entities)")}
        for col,ddl in (("display_name_short","TEXT"),("visibility_class","TEXT"),("label_priority","INTEGER"),("spatial_regime","TEXT"),("image_prompt","TEXT"),("image_prompt_status","TEXT"),("image_prompt_version","TEXT")):
            if col not in entity_cols: self.conn.execute(f"ALTER TABLE entities ADD COLUMN {col} {ddl}")
        knowledge_cols={r[1] for r in self.conn.execute("PRAGMA table_info(knowledge_entities)")}
        for col,ddl in (("display_name_short","TEXT"),("image_prompt","TEXT"),("image_prompt_status","TEXT"),("image_prompt_version","TEXT")):
            if col not in knowledge_cols: self.conn.execute(f"ALTER TABLE knowledge_entities ADD COLUMN {col} {ddl}")
        infra_cols={r[1] for r in self.conn.execute("PRAGMA table_info(infrastructure_nodes)")}
        for col in ("entity_id","region_entity_id","parent_entity_id"):
            if col not in infra_cols: self.conn.execute(f"ALTER TABLE infrastructure_nodes ADD COLUMN {col} TEXT")
        org_cols={r[1] for r in self.conn.execute("PRAGMA table_info(organizations)")}
        if "region_entity_id" not in org_cols: self.conn.execute("ALTER TABLE organizations ADD COLUMN region_entity_id TEXT")
        self.conn.execute("INSERT INTO meta(key,value) VALUES('legacy_nodes_status','DEPRECATED_EMPTY_v0.7') ON CONFLICT(key) DO UPDATE SET value=excluded.value")
        self.conn.execute(
            "INSERT INTO meta(key,value) VALUES('schema_version',?) ON CONFLICT(key) DO NOTHING",
            (DB_SCHEMA_VERSION,),
        )
        self.conn.commit()

    def seed_reference_data(self) -> None:
        rows = [("SOL", "Sun", "STAR", None, None, GLYPH_PX["SOL"], "HELIOCENTRIC_ORIGIN")]
        rows.extend((oid,name,kind,"SOL",command,GLYPH_PX[oid],"JPL_HORIZONS_VECTORS") for oid,name,command,kind in OBJECTS)
        rows.extend((mid,name,"MOON",pid,command,GLYPH_PX[mid],"JPL_HORIZONS_LOCAL_OR_DISPLAY_FALLBACK") for mid,name,command,kind,pid,a,p,pc in MOON_OBJECTS)
        self.conn.executemany("""
            INSERT INTO entities(entity_id,name,entity_class,parent_entity_id,source_command,glyph_px,provenance)
            VALUES(?,?,?,?,?,?,?)
            ON CONFLICT(entity_id) DO UPDATE SET
                name=excluded.name,
                entity_class=excluded.entity_class,
                parent_entity_id=excluded.parent_entity_id,
                source_command=excluded.source_command,
                glyph_px=excluded.glyph_px,
                provenance=excluded.provenance
        """, rows)
        self.conn.executemany("""INSERT INTO entities(entity_id,name,entity_class,parent_entity_id,source_command,glyph_px,provenance)
            VALUES(?,?,?,?,NULL,0,?) ON CONFLICT(entity_id) DO UPDATE SET name=excluded.name,entity_class=excluded.entity_class,parent_entity_id=excluded.parent_entity_id,provenance=excluded.provenance""",
            [(eid,name,kind,parent,"CANON_SPATIAL_REGION_v0.7") for eid,name,kind,parent in REGION_ENTITIES])

        source = "LOOM_ATLAS_v3.2_CANON_I_v2.4_BOOTSTRAP_PROJECTION"
        for entity_id, a in ATLAS_MINI.items():
            exists = self.conn.execute(
                "SELECT 1 FROM atlas_profiles WHERE entity_id=?", (entity_id,)
            ).fetchone()
            if exists:
                continue
            self.conn.execute("""
                INSERT INTO atlas_profiles(entity_id,title,bio,synth,status,summary,source)
                VALUES(?,?,?,?,?,?,?)
            """, (entity_id, a.get("title", entity_id), a.get("bio"), a.get("synth"),
                    a.get("status"), a.get("summary"), source))
            mobility = a.get("mobility") or {}
            self.conn.executemany(
                "INSERT INTO atlas_mobility(entity_id,attribute_key,attribute_value) VALUES(?,?,?)",
                [(entity_id, str(k), str(v)) for k, v in mobility.items()],
            )
            for node_id in a.get("nodes") or []:
                self.conn.execute("""
                    INSERT INTO nodes(node_id,parent_entity_id,name,node_class,source)
                    VALUES(?,?,?,?,?)
                """, (node_id, entity_id, None, None, source))
        self.conn.execute("DELETE FROM nodes")
        self.conn.executemany("INSERT INTO provenance_sources(source_id,source_class,citation,authority_status) VALUES(?,?,?,?) ON CONFLICT(source_id) DO UPDATE SET citation=excluded.citation,authority_status=excluded.authority_status", [
            ("JPL_HORIZONS","EPHEMERIS","JPL Horizons vectors; J2000/ECLIPTIC; center recorded per state","NAVIGATION_AUTHORITY_WHEN_DIRECT"),
            ("NAV_LOCAL_REFERENCE","REFERENCE_ORBIT","LOOM Navigator local-system reference radii/periods","DISPLAY_REFERENCE"),
            ("CANON_ATLAS","CANON","LOOM Atlas v3.2 / CANON I v2.4","GOVERNING_CANON")])
        # v0.6 universal celestial/navigation seed.
        dyn=[]
        for oid,name,command,kind in OBJECTS:
            dyn.append((oid,"SOL",command,"10",None,None,None,None,None,None,None,"STATE_VECTOR_AUTHORITY","JPL_HORIZONS/NAVIGATOR_POLICY"))
        for mid,name,command,kind,pid,a,p,pc in MOON_OBJECTS:
            dyn.append((mid,pid,command,pc,float(a),float(p),None,None,None,None,None,"ORBIT_REFERENCE_PLUS_RUNTIME_STATE","LOOM_NAVIGATOR_LOCAL_SYSTEMS/JPL_HORIZONS"))
        self.conn.executemany("""INSERT INTO celestial_dynamics(entity_id,primary_gravity_parent_id,horizons_command,parent_center_command,reference_orbit_radius_km,orbital_period_days,gm_km3_s2,mean_radius_km,soi_radius_km,hill_radius_km,atmosphere_class,metadata_status,source) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(entity_id) DO UPDATE SET primary_gravity_parent_id=excluded.primary_gravity_parent_id,horizons_command=excluded.horizons_command,parent_center_command=excluded.parent_center_command,reference_orbit_radius_km=excluded.reference_orbit_radius_km,orbital_period_days=excluded.orbital_period_days,metadata_status=excluded.metadata_status,source=excluded.source""",dyn)
        # Ceres physical constants are explicitly preserved by governing ship-operations canon.
        self.conn.execute("UPDATE celestial_dynamics SET gm_km3_s2=62.6284,mean_radius_km=469.7,metadata_status='CANON_PHYSICAL_ANCHOR' WHERE entity_id='CER'")
        rows84=load_body_zone_census(); bzsrc="CANON_I_v2.4 / Solar System Master Model v3.1 / body-zone census"
        self.conn.executemany("""INSERT INTO body_zone_census(system,body_or_network,zone_or_network,location_class,bio_residents,synthetic_persons,effective_family_gravity_g,primary_role,bio_status,synthetic_status,biological_residence_function,family_residence_interpretation,source) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(system,body_or_network,zone_or_network) DO UPDATE SET location_class=excluded.location_class,bio_residents=excluded.bio_residents,synthetic_persons=excluded.synthetic_persons,effective_family_gravity_g=excluded.effective_family_gravity_g,primary_role=excluded.primary_role,bio_status=excluded.bio_status,synthetic_status=excluded.synthetic_status,biological_residence_function=excluded.biological_residence_function,family_residence_interpretation=excluded.family_residence_interpretation,source=excluded.source""",[(r['system'],r['body_or_network'],r['zone_or_network'],r['location_class'],r['bio_residents'],r['synthetic_persons'],r.get('effective_family_gravity_g'),r['primary_role'],r['bio_status'],r['synthetic_status'],r['biological_residence_function'],r['family_residence_interpretation'],bzsrc) for r in rows84])
        # Promote each first-class moon/asteroid to an Atlas profile using exact Master Model allocations where present.
        name_by_id={x[0]:x[1] for x in BELT_OBJECTS}; name_by_id.update({x[0]:x[1] for x in MOON_OBJECTS})
        system_by_id={x[0]:x[4] for x in MOON_OBJECTS}
        parent_name={"EA":"Earth","MA":"Mars","JU":"Jupiter","SA":"Saturn","UR":"Uranus","NE":"Neptune","PL":"Kuiper"}
        for eid,nm in name_by_id.items():
            rr=self.conn.execute("SELECT SUM(bio_residents) bio,SUM(synthetic_persons) synth,GROUP_CONCAT(DISTINCT primary_role) roles FROM body_zone_census WHERE body_or_network=?",(nm,)).fetchone()
            if rr and rr['bio'] is not None:
                title=nm; summary=(rr['roles'] or '').replace(',', '; '); bio=f"{rr['bio']:.0f}"; synth=f"{rr['synth']:.0f}"; status='MASTER MODEL v3.1'
            else:
                title=nm; summary='First-class astronomical object. No dedicated body-level demographic allocation is promoted in the current Master Model.'; bio='—'; synth='—'; status='ASTRONOMICAL ENTITY'
            self.conn.execute("INSERT INTO atlas_profiles(entity_id,title,bio,synth,status,summary,source) VALUES(?,?,?,?,?,?,?) ON CONFLICT(entity_id) DO NOTHING",(eid,title,bio,synth,status,summary,bzsrc))
            scopes=[]
            if eid in system_by_id: scopes=[parent_name.get(system_by_id[eid],system_by_id[eid]),nm]
            elif eid in name_by_id: scopes=['Belt Majors',nm]
            for sc in scopes: self.conn.execute("INSERT OR IGNORE INTO entity_scopes(entity_id,scope_value) VALUES(?,?)",(eid,sc))
        # Full structured canon projection. These tables are authoritative read-only
        # projections of the bundled Atlas/Canon sources and are refreshed by seed version.
        c = load_canon_seed()
        source = c["atlas_source"]
        self.conn.executemany(
            "INSERT INTO census_records(region,biological,synthetic,canon_status,source) VALUES(?,?,?,?,?) "
            "ON CONFLICT(region) DO UPDATE SET biological=excluded.biological,synthetic=excluded.synthetic,canon_status=excluded.canon_status,source=excluded.source",
            [(r[0],r[1],r[2],r[3],source) for r in c["census"]],
        )
        self.conn.executemany(
            "INSERT INTO region_mobility(region,bulk_torch,metric_traffic,loom_access,shipbuilding,heavy_repair,metric_overhaul,feeder_density,transport_role,source) VALUES(?,?,?,?,?,?,?,?,?,?) "
            "ON CONFLICT(region) DO UPDATE SET bulk_torch=excluded.bulk_torch,metric_traffic=excluded.metric_traffic,loom_access=excluded.loom_access,shipbuilding=excluded.shipbuilding,heavy_repair=excluded.heavy_repair,metric_overhaul=excluded.metric_overhaul,feeder_density=excluded.feeder_density,transport_role=excluded.transport_role,source=excluded.source",
            [tuple(r)+ (source,) for r in c["mobility"]],
        )
        self.conn.executemany(
            "INSERT INTO infrastructure_nodes(node_id,node_name,system,parent_body,traffic,facility_type,commercial_1,commercial_2,commercial_regime,civil_authority,administrative_authority,security_authority,synthetic_constituency_1,institutional_morphology,source) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) "
            "ON CONFLICT(node_id) DO UPDATE SET node_name=excluded.node_name,system=excluded.system,parent_body=excluded.parent_body,traffic=excluded.traffic,facility_type=excluded.facility_type,commercial_1=excluded.commercial_1,commercial_2=excluded.commercial_2,commercial_regime=excluded.commercial_regime,civil_authority=excluded.civil_authority,administrative_authority=excluded.administrative_authority,security_authority=excluded.security_authority,synthetic_constituency_1=excluded.synthetic_constituency_1,institutional_morphology=excluded.institutional_morphology,source=excluded.source",
            [tuple(r)+(c["canon_source"],) for r in c["nodes"]],
        )
        self.conn.executemany(
            "INSERT INTO organizations(org_name,org_class,region,role,boundary,source) VALUES(?,?,?,?,?,?) "
            "ON CONFLICT(org_name) DO UPDATE SET org_class=excluded.org_class,region=excluded.region,role=excluded.role,boundary=excluded.boundary,source=excluded.source",
            [(o["name"],o["org_class"],o["region"],o["role"],o["boundary"],c["org_source"]) for o in c["organizations"]],
        )
        self.conn.executemany(
            "INSERT INTO regional_morphology(system,political_morphology,network_form,civil_authorities,administrative_authorities,security_authorities,source) VALUES(?,?,?,?,?,?,?) "
            "ON CONFLICT(system) DO UPDATE SET political_morphology=excluded.political_morphology,network_form=excluded.network_form,civil_authorities=excluded.civil_authorities,administrative_authorities=excluded.administrative_authorities,security_authorities=excluded.security_authorities,source=excluded.source",
            [tuple(r)+(c["org_source"],) for r in c["morphology"]],
        )
        self.conn.executemany(
            "INSERT INTO canon_source_sections(section_title,content,source) VALUES(?,?,?) "
            "ON CONFLICT(section_title) DO UPDATE SET content=excluded.content,source=excluded.source",
            [(title,content,source) for title,content in c["source_sections"]],
        )
        # Refresh legacy canonical scopes without erasing scopes for newly promoted
        # first-class moons/asteroids.  v0.5.x used a table-wide DELETE here, which
        # would silently detach new celestial objects from their body/system Atlas rows.
        for _eid in c["entity_scopes"]:
            self.conn.execute("DELETE FROM entity_scopes WHERE entity_id=?", (_eid,))
        self.conn.executemany("INSERT INTO entity_scopes(entity_id,scope_value) VALUES(?,?)",
            [(eid,s) for eid,vals in c["entity_scopes"].items() for s in vals])
        self.conn.executemany(
            "INSERT INTO atlas_subfeatures(parent_entity_id,name,intro,fields_json,source_section,source) VALUES(?,?,?,?,?,?) "
            "ON CONFLICT(parent_entity_id,name) DO UPDATE SET intro=excluded.intro,fields_json=excluded.fields_json,source_section=excluded.source_section,source=excluded.source",
            [(x["parent_entity_id"],x["name"],x["intro"],json.dumps(x["fields"],ensure_ascii=False),x["source_section"],source) for x in c["subfeatures"]],
        )
        for r in self.conn.execute("SELECT node_id,node_name,facility_type,system,parent_body,source FROM infrastructure_nodes").fetchall():
            region_id=REGION_SCOPE_MAP.get(r["system"] or "")
            parent_id=REGION_SCOPE_MAP.get(r["parent_body"] or "") or region_id
            self.conn.execute("""INSERT INTO entities(entity_id,name,entity_class,parent_entity_id,source_command,glyph_px,provenance) VALUES(?,?,?, ?,NULL,0,?) ON CONFLICT(entity_id) DO UPDATE SET name=excluded.name,entity_class=excluded.entity_class,parent_entity_id=excluded.parent_entity_id,provenance=excluded.provenance""",
                              (r["node_id"],r["node_name"],"INFRASTRUCTURE",parent_id,r["source"]))
            self.conn.execute("UPDATE infrastructure_nodes SET entity_id=?,region_entity_id=?,parent_entity_id=? WHERE node_id=?",
                (r["node_id"],region_id,parent_id,r["node_id"]))
        for r in self.conn.execute("SELECT org_name,region FROM organizations").fetchall():
            self.conn.execute("UPDATE organizations SET region_entity_id=? WHERE org_name=?",(REGION_SCOPE_MAP.get(r["region"] or ""),r["org_name"]))
        for r in self.conn.execute("SELECT * FROM region_mobility").fetchall():
            eid=REGION_SCOPE_MAP.get(r["region"] or "")
            if eid:
                self.conn.execute("""INSERT INTO transport_hubs(entity_id,traffic_class_torch,traffic_class_metric,loom_access_class,shipyard_class,heavy_repair,metric_overhaul,local_feeder_class,primary_transport_role,model_status,provenance) VALUES(?,?,?,?,?,?,?,?,?,'QUALITATIVE_CANON_ONLY',?) ON CONFLICT(entity_id) DO UPDATE SET traffic_class_torch=excluded.traffic_class_torch,traffic_class_metric=excluded.traffic_class_metric,loom_access_class=excluded.loom_access_class,shipyard_class=excluded.shipyard_class,heavy_repair=excluded.heavy_repair,metric_overhaul=excluded.metric_overhaul,local_feeder_class=excluded.local_feeder_class,primary_transport_role=excluded.primary_transport_role,model_status=excluded.model_status,provenance=excluded.provenance""",
                    (eid,r['bulk_torch'],r['metric_traffic'],r['loom_access'],r['shipbuilding'],r['heavy_repair'],r['metric_overhaul'],r['feeder_density'],r['transport_role'],r['source']))

        self._seed_spatial_infrastructure()
        self._seed_knowledge_graph()
        self._seed_canon_exploitation_profiles()
        self._seed_visual_metadata()
        self.conn.execute("INSERT INTO meta(key,value) VALUES('canon_seed_version',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (CANON_SEED_VERSION,))
        self.conn.commit()

    @staticmethod
    def _facility_narrative_role(facility_type: str | None) -> str:
        """Conservative reader-facing role phrase derived only from canonical facility class."""
        f=(facility_type or 'INFRASTRUCTURE').upper()
        exact={
            'SURFACE_SPACEPORT':'surface launch and orbital-interface spaceport',
            'SURFACE_REENTRY_PORT':'surface reentry and recovery port',
            'SURFACE_MEGA_PORT':'major surface lift, logistics and manufacturing port',
            'SURFACE_INBODY_PORT':'surface/in-body industrial lift and transfer port',
            'SURFACE_RESOURCE_PORT':'surface resource and logistics terminal',
            'SURFACE_CARGO_GRID':'distributed surface cargo and handling network',
            'ORBITAL_HABITAT_PORT':'orbital habitat and traffic exchange',
            'ORBITAL_SHIPYARD':'orbital shipyard and heavy service complex',
            'ORBITAL_EXCHANGE':'orbital traffic and commercial exchange',
            'ATTACHED_MOON_PORT':'moon-attached transfer and logistics port',
            'STRATEGIC_PORT':'restricted strategic anchorage/control port',
            'ROBOTIC_ATMOSPHERIC_RESOURCE_PORT':'robotic atmospheric-resource control and logistics node',
            'AEROSTAT_PORT':'aerostat habitat/logistics port',
            'SCIENCE_PORT':'science and research logistics node',
            'PROTECTED_SCIENCE_PORT':'protected science and controlled-access logistics node',
            'QUARANTINE_PORT':'quarantine and controlled-transfer facility',
            'METROLOGY_PORT':'metrology, calibration and standards-support facility',
            'ASSAY_PORT':'assay, characterization and certified-material transfer facility',
            'FREE_SPACE_HABITAT_PORT':'free-space habitat and traffic port',
            'ROTATING_HABITAT_PORT':'rotating-habitat and traffic port',
            'KBO_PORT':'Kuiper-object logistics and service port',
            'HELIOCENTRIC_STATION':'independent heliocentric station',
            'DEEP_SPACE_RELAY':'deep-space relay and navigation-support node',
        }
        if f in exact:return exact[f]
        if 'SHIPYARD' in f or 'YARD' in f:return 'shipyard and heavy service facility'
        if 'HABITAT' in f:return 'habitat and traffic facility'
        if 'SCIENCE' in f or 'OBSERV' in f:return 'science, observation and research-support facility'
        if 'RELAY' in f or 'SENSOR' in f:return 'relay, sensor and navigation-support facility'
        if 'METROLOGY' in f:return 'metrology and standards-support facility'
        if 'RESOURCE' in f or 'MINING' in f:return 'resource-production and logistics facility'
        if 'SURFACE' in f:return 'surface logistics and operations facility'
        if 'ORBITAL' in f:return 'orbital operations and traffic facility'
        if 'FREE_SPACE' in f:return 'free-space operations and traffic facility'
        if 'PORT' in f:return 'transport and logistics port'
        return f.lower().replace('_',' ')

    @staticmethod
    def _traffic_narrative(traffic: str | None) -> str:
        t=(traffic or '').upper().strip()
        return {
            'EXTREME':'Its EXTREME traffic class marks it as one of the canonical network’s major high-volume hubs.',
            'VERY HIGH':'Its VERY HIGH traffic class marks it as a major regional traffic node.',
            'HIGH':'Its HIGH traffic class indicates sustained, important regional operations.',
            'MEDIUM':'Its MEDIUM traffic class indicates regular but not dominant network activity.',
            'MODERATE':'Its MODERATE traffic class indicates regular but not dominant network activity.',
            'LOW':'Its LOW traffic class indicates a specialized or lightly used node rather than a major hub.',
            'RESTRICTED':'Its RESTRICTED traffic class indicates controlled access rather than ordinary high-volume traffic.',
            'LOW / RESTRICTED':'Its LOW / RESTRICTED traffic class indicates sparse, controlled access.',
        }.get(t, f'Its canonical traffic class is {traffic}.' if traffic else 'No quantitative or qualitative traffic class is promoted beyond the current infrastructure record.')

    def _infrastructure_place_narrative(self, n: sqlite3.Row) -> tuple[str,str,dict]:
        """Narrative assembled only from canonical node fields plus already-governing system context."""
        name=n['node_name']; parent=n['parent_body'] or n['system'] or 'Solar space'; system=n['system'] or parent
        role=self._facility_narrative_role(n['facility_type'])
        sentences=[f"{name} is a canonical {role} at {parent}" + (f" in the {system} network." if system and system!=parent else '.')]
        sentences.append(self._traffic_narrative(n['traffic']))
        if n['commercial_1'] and n['commercial_2']:
            sentences.append(f"Its recorded commercial environment includes {n['commercial_1']} and {n['commercial_2']}, under a {n['commercial_regime'] or 'plural'} commercial regime.")
        elif n['commercial_1']:
            sentences.append(f"Its recorded commercial environment names {n['commercial_1']}" + (f" under a {n['commercial_regime']} regime." if n['commercial_regime'] else '.'))
        auth=[]
        if n['civil_authority']:auth.append(f"civil authority: {n['civil_authority']}")
        if n['administrative_authority']:auth.append(f"administration: {n['administrative_authority']}")
        if n['security_authority']:auth.append(f"security/rescue: {n['security_authority']}")
        if auth:sentences.append('Its canonical authority stack separates ' + '; '.join(auth) + '.')
        if n['synthetic_constituency_1']:
            sentences.append(f"The named synthetic constituency is {n['synthetic_constituency_1']}.")
        boundary='Exact physical scale, berth count, annual throughput, staffing and operating economics are not promoted by this record; rendered position remains a provisional engineering placement unless separately navigation-authoritative.'
        fields={
            'facility_role':role,
            'facility_type':n['facility_type'],
            'traffic_class':n['traffic'],
            'system':n['system'],
            'parent_body':n['parent_body'],
            'commercial_primary':n['commercial_1'],
            'commercial_secondary':n['commercial_2'],
            'commercial_regime':n['commercial_regime'],
            'civil_authority':n['civil_authority'],
            'administrative_authority':n['administrative_authority'],
            'security_authority':n['security_authority'],
            'synthetic_constituency':n['synthetic_constituency_1'],
            'institutional_morphology':n['institutional_morphology'],
            'epistemic_status':'DERIVED_FROM_CANON_NODE_FIELDS',
            'boundary':boundary,
        }
        return ' '.join(s for s in sentences if s),boundary,fields

    def _enrich_infrastructure_place_narratives(self) -> None:
        """Give every canonical infrastructure node a reader-facing place profile."""
        for n in self.conn.execute("SELECT * FROM infrastructure_nodes ORDER BY node_id").fetchall():
            eid=n['entity_id'] or n['node_id']
            if not self.conn.execute("SELECT 1 FROM entities WHERE entity_id=?",(eid,)).fetchone():continue
            desc,boundary,fields=self._infrastructure_place_narrative(n)
            self.conn.execute("UPDATE atlas_profiles SET summary=?,source=? WHERE entity_id=?",(desc,'CANON I v2.4 infrastructure/jurisdiction map · narrative projection',eid))
            self.conn.execute("UPDATE knowledge_entities SET quick_description=?,boundary_note=?,source_detail=? WHERE spatial_entity_id=?",(desc,boundary,f'DERIVED_FROM_CANON_NODE_FIELDS · infrastructure node {n["node_id"]}',eid))
            self.conn.execute("""INSERT INTO atlas_subfeatures(parent_entity_id,name,intro,fields_json,source_section,source)
                VALUES(?,?,?,?,?,?) ON CONFLICT(parent_entity_id,name) DO UPDATE SET intro=excluded.intro,fields_json=excluded.fields_json,source_section=excluded.source_section,source=excluded.source""",
                (eid,'PLACE PROFILE · '+n['node_name'],desc,json.dumps(fields,ensure_ascii=False),'Major infrastructure and jurisdiction map','CANON I v2.4'))

    def _enrich_earth_political_actor_narratives(self) -> None:
        """Promote the seven Earth blocs actually named by governing canon.

        Current CANON I explicitly leaves the exact 2226 territorial map open. We therefore
        expose only named bloc status and their canonical infrastructure authority assignments;
        no borders, formation dates, constitutions, capability scores or unlisted blocs are invented.
        """
        earth=self.conn.execute("SELECT * FROM regional_morphology WHERE system='Earth'").fetchone()
        if not earth:return
        blocs=[x.strip() for x in (earth['civil_authorities'] or '').split(';') if x.strip()]
        for name in blocs:
            ke=self.conn.execute("SELECT * FROM knowledge_entities WHERE canonical_name=?",(name,)).fetchone()
            if not ke:continue
            civil=self.conn.execute("SELECT node_id,node_name,administrative_authority,security_authority,traffic,facility_type FROM infrastructure_nodes WHERE civil_authority=? ORDER BY node_id",(name,)).fetchall()
            security=self.conn.execute("SELECT node_id,node_name FROM infrastructure_nodes WHERE security_authority=? ORDER BY node_id",(name,)).fetchall()
            facilities=[r['node_name'] for r in civil]
            admins=[]
            for r in civil:
                a=(r['administrative_authority'] or '').strip()
                if a and a not in admins:admins.append(a)
            desc=f"{name} is one of the named terrestrial states/blocs in Earth’s plural 2226 political order. Current canon leaves the exact 2226 territorial map open and preserves territorial sovereignty as plural rather than replacing Earth with a single planetary government."
            if facilities:
                desc+=f" In the major infrastructure register it holds civil authority at {', '.join(facilities)}."
            if admins:
                desc+=f" Network administration at those facilities is separately assigned to {', '.join(admins)}."
            if security and set(r['node_name'] for r in security)==set(facilities):
                desc+=" The same bloc also holds the listed security/rescue authority at those registered facilities."
            boundary='Exact territorial borders, constitutional succession, internal political structure, total economic/military capability and any unlisted facilities remain open unless separately fixed by canon. Infrastructure jurisdiction must not be read as a complete territorial map.'
            self.conn.execute("UPDATE knowledge_entities SET quick_description=?,boundary_note=?,source_detail=? WHERE noun_id=?",
                              (desc,boundary,'CANON I v2.4 Earth institutional morphology + major infrastructure/jurisdiction map',ke['noun_id']))
            fields={
                'actor_type':'TERRESTRIAL_STATE_OR_BLOC',
                'political_morphology':earth['political_morphology'],
                'network_form':earth['network_form'],
                'major_registered_facilities':facilities,
                'associated_administrative_authorities':admins,
                'security_authority_at_registered_facilities':[r['node_name'] for r in security],
                'epistemic_status':'CANONICAL_NAMED_BLOC / MAP_OPEN',
                'boundary':boundary,
            }
            self.conn.execute("""INSERT INTO atlas_subfeatures(parent_entity_id,name,intro,fields_json,source_section,source)
                VALUES(?,?,?,?,?,?) ON CONFLICT(parent_entity_id,name) DO UPDATE SET intro=excluded.intro,fields_json=excluded.fields_json,source_section=excluded.source_section,source=excluded.source""",
                ('EA','POLITICAL ACTOR · '+name,desc,json.dumps(fields,ensure_ascii=False),'Regional institutional morphology / Major infrastructure and jurisdiction map','CANON I v2.4'))

    def _seed_canon_exploitation_profiles(self) -> None:
        """Project already-promoted Solar canon into entity-level GIS profile tables.

        This routine is intentionally conservative: it copies/restructures governing
        census, mobility, infrastructure and institutional records. It does not infer
        quantitative engineering capacity, energy, OD demand, throughput or route links.
        """
        source_id="CANON_ATLAS"
        # Rebuild only canon-derived profile tables owned by this projection.
        self.conn.execute("DELETE FROM entity_authorities WHERE source_id=?",(source_id,))
        self.conn.execute("DELETE FROM entity_economic_profiles WHERE source_id=?",(source_id,))
        self.conn.execute("DELETE FROM entity_transport_profiles WHERE source_id=?",(source_id,))
        self.conn.execute("DELETE FROM entity_demographic_profiles WHERE source_id=?",(source_id,))

        mobility_region_for_system={
            'Earth':'Earth–Luna / cislunar','Earth Orbit':'Earth–Luna / cislunar','Moon':'Earth–Luna / cislunar',
            'Mars':'Mars system','Ceres':'Ceres + Belt network','Belt Majors':'Ceres + Belt network','Belt/Psyche':'Ceres + Belt network',
            'Mercury':'Mercury + sunward industry','Venus':'Venus','Jupiter':'Jupiter system','Saturn':'Saturn system',
            'Uranus':'Uranus system','Neptune':'Neptune system','Kuiper':'Kuiper / scattered / detached',
            'Oort':'Oort','Heliocentric':'Distributed heliocentric network'
        }
        mobility_entity_for_region={
            'Earth–Luna / cislunar':'CISLUNAR','Mars system':'MA','Ceres + Belt network':'BELT',
            'Mercury + sunward industry':'ME','Venus':'VE','Jupiter system':'JU','Saturn system':'SA',
            'Uranus system':'UR','Neptune system':'NE','Kuiper / scattered / detached':'KUIPER',
            'Oort':'OORT','Distributed heliocentric network':'HELIOCENTRIC'
        }
        demographic_entity_for_system={
            'Earth':'EA','Earth Orbit':'EARTH_ORBIT','Moon':'LU','Mars':'MA','Mercury':'ME','Venus':'VE','Ceres':'CER',
            'Belt Majors':'BELT','Jupiter':'JU','Saturn':'SA','Uranus':'UR','Neptune':'NE','Kuiper':'KUIPER','Oort':'OORT','Heliocentric':'HELIOCENTRIC'
        }

        # Region/system demographic totals: these are exact sums of the governing 84-row allocation table.
        for system,eid in demographic_entity_for_system.items():
            if not self.conn.execute("SELECT 1 FROM entities WHERE entity_id=?",(eid,)).fetchone(): continue
            r=self.conn.execute("SELECT SUM(bio_residents) bio,SUM(synthetic_persons) synth,COUNT(*) n FROM body_zone_census WHERE system=?",(system,)).fetchone()
            if not r or not r['n']: continue
            self.conn.execute("""INSERT INTO entity_demographic_profiles(entity_id,biological_residents,synthetic_persons,habitation_class,epistemic_status,source_id,notes)
                VALUES(?,?,?,?,?,?,?) ON CONFLICT(entity_id) DO UPDATE SET biological_residents=excluded.biological_residents,synthetic_persons=excluded.synthetic_persons,habitation_class=excluded.habitation_class,epistemic_status=excluded.epistemic_status,source_id=excluded.source_id,notes=excluded.notes""",
                (eid,float(r['bio'] or 0),float(r['synth'] or 0),'SYSTEM_OR_NETWORK_TOTAL','DERIVED_CANON',source_id,f'Conserved {system} total summed from governing body_zone_census rows.'))

        # First-class moons/small bodies: exact body allocations where the Master Model has them.
        body_map=dict(INFRA_PARENT_MAP)
        body_map.update({r['name']:r['entity_id'] for r in self.conn.execute("SELECT entity_id,name FROM entities WHERE entity_class IN ('MOON','ASTEROID','PLANET','DWARF_PLANET','SYSTEM_BARYCENTER')").fetchall()})
        for r in self.conn.execute("SELECT system,body_or_network,SUM(bio_residents) bio,SUM(synthetic_persons) synth,COUNT(*) n FROM body_zone_census GROUP BY system,body_or_network").fetchall():
            body=r['body_or_network']; eid=body_map.get(body)
            if not eid or eid in set(demographic_entity_for_system.values()): continue
            if not self.conn.execute("SELECT 1 FROM entities WHERE entity_id=?",(eid,)).fetchone(): continue
            self.conn.execute("""INSERT INTO entity_demographic_profiles(entity_id,biological_residents,synthetic_persons,habitation_class,epistemic_status,source_id,notes)
                VALUES(?,?,?,?,?,?,?) ON CONFLICT(entity_id) DO UPDATE SET biological_residents=excluded.biological_residents,synthetic_persons=excluded.synthetic_persons,habitation_class=excluded.habitation_class,epistemic_status=excluded.epistemic_status,source_id=excluded.source_id,notes=excluded.notes""",
                (eid,float(r['bio'] or 0),float(r['synth'] or 0),'BODY_ALLOCATION','DERIVED_CANON',source_id,f'Exact {body} allocation summed from governing body_zone_census rows in {r["system"]}.'))

        # Canonical regional transport classes become entity profiles for the mapped system/network.
        for r in self.conn.execute("SELECT * FROM region_mobility").fetchall():
            eid=mobility_entity_for_region.get(r['region'] or '') or REGION_SCOPE_MAP.get(r['region'] or '')
            if not eid or not self.conn.execute("SELECT 1 FROM entities WHERE entity_id=?",(eid,)).fetchone(): continue
            self.conn.execute("""INSERT INTO entity_transport_profiles(entity_id,regional_context,bulk_torch,metric_traffic,loom_access,shipbuilding,heavy_repair,metric_overhaul,feeder_density,transport_role,epistemic_status,source_id,source_detail)
                VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(entity_id) DO UPDATE SET regional_context=excluded.regional_context,bulk_torch=excluded.bulk_torch,metric_traffic=excluded.metric_traffic,loom_access=excluded.loom_access,shipbuilding=excluded.shipbuilding,heavy_repair=excluded.heavy_repair,metric_overhaul=excluded.metric_overhaul,feeder_density=excluded.feeder_density,transport_role=excluded.transport_role,epistemic_status=excluded.epistemic_status,source_id=excluded.source_id,source_detail=excluded.source_detail""",
                (eid,r['region'],r['bulk_torch'],r['metric_traffic'],r['loom_access'],r['shipbuilding'],r['heavy_repair'],r['metric_overhaul'],r['feeder_density'],r['transport_role'],'CANONICAL_CLASS',source_id,r['source']))

        # Repair the legacy transport_hubs projection too: older mapping only materialized region names that happened to match REGION_SCOPE_MAP keys.
        for r in self.conn.execute("SELECT * FROM region_mobility").fetchall():
            eid=mobility_entity_for_region.get(r['region'] or '') or REGION_SCOPE_MAP.get(r['region'] or '')
            if not eid: continue
            self.conn.execute("""INSERT INTO transport_hubs(entity_id,traffic_class_torch,traffic_class_metric,loom_access_class,shipyard_class,heavy_repair,metric_overhaul,local_feeder_class,primary_transport_role,model_status,provenance)
                VALUES(?,?,?,?,?,?,?,?,?,'QUALITATIVE_CANON_ONLY',?) ON CONFLICT(entity_id) DO UPDATE SET traffic_class_torch=excluded.traffic_class_torch,traffic_class_metric=excluded.traffic_class_metric,loom_access_class=excluded.loom_access_class,shipyard_class=excluded.shipyard_class,heavy_repair=excluded.heavy_repair,metric_overhaul=excluded.metric_overhaul,local_feeder_class=excluded.local_feeder_class,primary_transport_role=excluded.primary_transport_role,model_status=excluded.model_status,provenance=excluded.provenance""",
                (eid,r['bulk_torch'],r['metric_traffic'],r['loom_access'],r['shipbuilding'],r['heavy_repair'],r['metric_overhaul'],r['feeder_density'],r['transport_role'],r['source']))

        # Infrastructure-level economics, authorities and local traffic.
        authority_roles=(('civil_authority','CIVIL'),('administrative_authority','ADMINISTRATIVE'),('security_authority','SECURITY'))
        for n in self.conn.execute("SELECT * FROM infrastructure_nodes ORDER BY node_id").fetchall():
            eid=n['entity_id'] or n['node_id']
            if not self.conn.execute("SELECT 1 FROM entities WHERE entity_id=?",(eid,)).fetchone(): continue
            def noun_id(name):
                if not name: return None
                rr=self.conn.execute("SELECT noun_id FROM knowledge_entities WHERE canonical_name=?",(name,)).fetchone()
                return rr['noun_id'] if rr else None
            p1=noun_id(n['commercial_1']); p2=noun_id(n['commercial_2'])
            self.conn.execute("""INSERT INTO entity_economic_profiles(entity_id,primary_commercial_noun_id,secondary_commercial_noun_id,commercial_regime,institutional_morphology,epistemic_status,source_id,source_detail)
                VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(entity_id) DO UPDATE SET primary_commercial_noun_id=excluded.primary_commercial_noun_id,secondary_commercial_noun_id=excluded.secondary_commercial_noun_id,commercial_regime=excluded.commercial_regime,institutional_morphology=excluded.institutional_morphology,epistemic_status=excluded.epistemic_status,source_id=excluded.source_id,source_detail=excluded.source_detail""",
                (eid,p1,p2,n['commercial_regime'],n['institutional_morphology'],'DERIVED_CANON',source_id,f'Infrastructure node {n["node_id"]}; {n["source"]}'))
            region=mobility_region_for_system.get(n['system'] or '') or mobility_region_for_system.get(n['parent_body'] or '')
            mr=self.conn.execute("SELECT * FROM region_mobility WHERE region=?",(region,)).fetchone() if region else None
            self.conn.execute("""INSERT INTO entity_transport_profiles(entity_id,local_traffic_class,regional_context,bulk_torch,metric_traffic,loom_access,shipbuilding,heavy_repair,metric_overhaul,feeder_density,transport_role,epistemic_status,source_id,source_detail)
                VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(entity_id) DO UPDATE SET local_traffic_class=excluded.local_traffic_class,regional_context=excluded.regional_context,bulk_torch=excluded.bulk_torch,metric_traffic=excluded.metric_traffic,loom_access=excluded.loom_access,shipbuilding=excluded.shipbuilding,heavy_repair=excluded.heavy_repair,metric_overhaul=excluded.metric_overhaul,feeder_density=excluded.feeder_density,transport_role=excluded.transport_role,epistemic_status=excluded.epistemic_status,source_id=excluded.source_id,source_detail=excluded.source_detail""",
                (eid,n['traffic'],region,mr['bulk_torch'] if mr else None,mr['metric_traffic'] if mr else None,mr['loom_access'] if mr else None,mr['shipbuilding'] if mr else None,mr['heavy_repair'] if mr else None,mr['metric_overhaul'] if mr else None,mr['feeder_density'] if mr else None,mr['transport_role'] if mr else None,'CANONICAL_CLASS',source_id,f'Local class from infrastructure node {n["node_id"]}; regional fields inherited from Atlas mobility row {region or "none"}.'))
            for col,role in authority_roles:
                name=n[col]; nid=noun_id(name)
                if not nid: continue
                self.conn.execute("""INSERT INTO entity_authorities(entity_id,authority_noun_id,authority_role,scope_text,epistemic_status,source_id,source_detail)
                    VALUES(?,?,?,?,?,?,?) ON CONFLICT(entity_id,authority_noun_id,authority_role) DO UPDATE SET scope_text=excluded.scope_text,epistemic_status=excluded.epistemic_status,source_id=excluded.source_id,source_detail=excluded.source_detail""",
                    (eid,nid,role,n['parent_body'] or n['system'],'DERIVED_CANON',source_id,f'Infrastructure node {n["node_id"]}; {n["source"]}'))
            # Reader-facing narrative is built after all profile/relationship rows exist.

        # Canon I body/network world-state registry: narrative-rich records absent from the legacy GIS seed.
        # Store them in the existing flexible Atlas subfeature layer and upgrade thin first-class body summaries.
        system_parent={
            'Earth':'EA','Earth Orbit':'EARTH_ORBIT','Moon':'LU','Mars':'MA','Mercury':'ME','Venus':'VE','Ceres':'CER',
            'Belt Majors':'BELT','Jupiter':'JU','Saturn':'SA','Uranus':'UR','Neptune':'NE','Kuiper':'KUIPER','Oort':'OORT','Heliocentric':'HELIOCENTRIC'
        }
        spatial_by_name={r['name']:r['entity_id'] for r in self.conn.execute("SELECT entity_id,name FROM entities").fetchall()}
        for wr in load_body_world_state_seed():
            body=wr['body_or_network']; system=wr['system']
            # Earth Orbit is a distinct network record even though body_or_network says Earth.
            direct_eid='EARTH_ORBIT' if system=='Earth Orbit' else (spatial_by_name.get(body) or INFRA_PARENT_MAP.get(body) or REGION_SCOPE_MAP.get(body))
            target=direct_eid or system_parent.get(system)
            if not target or not self.conn.execute("SELECT 1 FROM entities WHERE entity_id=?",(target,)).fetchone(): continue
            fields={
                'biological_residents':float(wr['biological_residents']) if wr['biological_residents'] else None,
                'synthetic_persons':float(wr['synthetic_persons']) if wr['synthetic_persons'] else None,
                'settlement_forms':wr['settlement_forms'],
                'primary_roles':wr['primary_roles'],
                'system_role':wr['system_role'],
                'political_structure':wr['political_structure'],
                'major_port_ids':wr['major_port_ids'],
                'network_governance_model':wr['network_governance_model'],
                'residence_semantics':wr['residence_semantics'],
                'bio_status':wr['bio_status'],
                'synthetic_status':wr['synthetic_status']
            }
            intro=f"{body} world-state registry record ({system})."
            self.conn.execute("""INSERT INTO atlas_subfeatures(parent_entity_id,name,intro,fields_json,source_section,source) VALUES(?,?,?,?,?,?)
                ON CONFLICT(parent_entity_id,name) DO UPDATE SET intro=excluded.intro,fields_json=excluded.fields_json,source_section=excluded.source_section,source=excluded.source""",
                (target,f'WORLD STATE · {body}',intro,json.dumps(fields,ensure_ascii=False),'4. Body/network world-state registry','CANON I v2.4'))
            if direct_eid and direct_eid==target:
                # Upgrade terse generated summaries using only registry language.
                role=wr['primary_roles'].replace('; ','; ')
                sysrole=wr['system_role']
                summary=role + (f". System context: {sysrole}." if sysrole and sysrole not in role else '.')
                self.conn.execute("UPDATE atlas_profiles SET summary=?,source=? WHERE entity_id=?",(summary,'CANON I v2.4 body/network world-state registry',target))
                self.conn.execute("UPDATE knowledge_entities SET quick_description=?,source_detail=? WHERE spatial_entity_id=?",(summary,f'Body/network world-state registry · {system} / {body}',target))

        self._enrich_infrastructure_place_narratives()
        self._enrich_earth_political_actor_narratives()
        self.conn.commit()

