            ("Dione Science & Industry Port","Dione Science Port"),
            ("Phoebe Irregular Survey Port","Phoebe Survey Port"),
            ("Triton Cryogenic Freight Terminal","Triton Cryo Terminal"),
            ("Nereid Science Transfer Station","Nereid Transfer"),
            ("Pluto–Charon Kuiper Exchange","Pluto–Charon Exchange"),
            ("Quaoar–Orcus Regional Exchange","Regional Kuiper Exchange"),
            ("Scattered-Disk Survey Anchorage","Scattered-Disk Survey"),
            ("Sedna Detached-Object Metrology Station","Sedna Metrology"),
            ("Inner-Oort Metrology Station Alpha","Oort Metrology Alpha"),
            ("Inner-Oort Relay Beta","Oort Relay Beta"),
