def demo_provider(command: str, epoch: datetime) -> StateVector:
    r = _DEMO_RADII[command]
    key = sum(ord(c) for c in command)
    phase = (key * 0.071 + epoch.timetuple().tm_yday * 0.017) % (2 * math.pi)
    zfrac = 0.0
    if command in ("9", "2;"):
        zfrac = 0.12
    elif command.endswith(";"):
        zfrac = 0.035
    x, y, z = r*math.cos(phase), r*math.sin(phase), r*zfrac*math.sin(phase*0.7)
    # Near-circular tangential speed about Sun. z velocity intentionally zero in fixture.
    speed = math.sqrt(MU_SUN_AU3_D2/r)
    vx, vy = -speed*math.sin(phase), speed*math.cos(phase)
    return StateVector(x, y, z, vx, vy, 0.0)


def demo_moon_provider(command: str, center_command: str, epoch: datetime) -> StateVector:
    for mid,name,cmd,kind,pid,a_km,period,parent in MOON_OBJECTS:
        if cmd==command:
            return circular_local_fallback(command,a_km,period,epoch)
    raise SolarSceneError(f"unknown demo moon {command}")


