GRAPH_DB_FILENAME = "LOOM_2226_GRAPH_LAYER_v0.1_candidate.sqlite3"

def graph_db_has_views(path: str | Path) -> bool:
    try:
        p = Path(path)
        if not p.exists():
            return False
        c = sqlite3.connect(f"file:{p}?mode=ro", uri=True)
        try:
            names = {r[0] for r in c.execute(
                "SELECT name FROM sqlite_master WHERE type='view' AND name IN ('v_graph_nodes','v_graph_display_edges')"
            )}
            return {"v_graph_nodes","v_graph_display_edges"} <= names
        finally:
            c.close()
    except Exception:
        return False

def discover_graph_db(world_db: str | Path, explicit: str | Path | None = None) -> Path | None:
    if explicit:
        p = Path(explicit)
        return p if graph_db_has_views(p) else None

    candidates = []
    try:
        wp = Path(world_db)
        if graph_db_has_views(wp):
            return wp
        if str(world_db) != ":memory:":
            candidates.append(wp.with_name(GRAPH_DB_FILENAME))
            # Any graph-enabled DB beside the production world DB.
            if wp.parent.exists():
                candidates.extend(wp.parent.glob("*.sqlite3"))
                candidates.extend(wp.parent.glob("*.sqlite"))
                candidates.extend(wp.parent.glob("*.db"))
    except Exception:
        pass

    roots = [
        Path("/storage/emulated/0/Download"),
        Path("/storage/emulated/0/Documents/LOOM/data"),
        Path("/storage/emulated/0/Documents"),
    ]
    for root in roots:
        candidates.append(root / GRAPH_DB_FILENAME)
        try:
            if root.exists():
                candidates.extend(root.glob("*.sqlite3"))
                candidates.extend(root.glob("*.sqlite"))
                candidates.extend(root.glob("*.db"))
        except Exception:
            pass

    # De-duplicate, validate the actual views, prefer newest valid DB.
    valid = []
    seen = set()
    for p in candidates:
        try:
            rp = str(Path(p))
            if rp in seen:
                continue
            seen.add(rp)
            if graph_db_has_views(p):
                valid.append(Path(p))
        except Exception:
            continue

    if not valid:
        return None
    valid.sort(key=lambda p: p.stat().st_mtime if p.exists() else 0, reverse=True)
    return valid[0]

def load_graph_view_payload(path: str | Path | None) -> dict:
    if not path:
        return {"nodes":[],"edges":[],"available":False}
    p = Path(path)
    c = sqlite3.connect(f"file:{p}?mode=ro", uri=True)
    c.row_factory = sqlite3.Row
    try:
        nodes = [dict(r) for r in c.execute("""
            SELECT node_key,node_domain,ontology_class,source_id,canonical_name,
                   brief_description,spatial_parent_entity_id,institution_noun_id,
                   spatial_entity_id,source_table
            FROM v_graph_nodes
        """)]
        edges = [dict(r) for r in c.execute("""
            SELECT display_degree,link_key,from_node_key,to_node_key,relationship_type,
                   relationship_domain,is_derived,context_entity_id,support_count,
                   from_domain,to_domain
            FROM v_graph_display_edges
        """)]
        return {
            "nodes":nodes,
            "edges":edges,
            "available":True,
            "path":str(p),
            "node_count":len(nodes),
            "edge_count":len(edges),
        }
    finally:
        c.close()

class SolarHandler(BaseHTTPRequestHandler):
    scene_json = b"{}"
    scene_core_json = b"{}"
    scene_bootstrap_json = b"{}"
    scene_geometry_json = b"{}"
    scene_details_json = b"{}"
    db_info_json = b"{}"
    graph_view_json = b'{"nodes":[],"edges":[],"available":false}'
    db_path = None
    media_db_path = None
    html = HTML.encode("utf-8")
    client_js = b""

    def do_GET(self):
        path = urlparse(self.path).path
        if path.startswith('/entity-media-status/') or path.startswith('/entity-thumbnail/') or path.startswith('/entity-image/'):
            print(f"MEDIA REQ    START {self.command} {path}")
        if path in ("/", "/index.html"):
            self._send(200, "text/html; charset=utf-8", self.html)
        elif path == "/app.js":
            self._send(200, "application/javascript; charset=utf-8", self.client_js)
        elif path == "/client-log":
            q = parse_qs(urlparse(self.path).query)
            stage = (q.get("stage") or ["?"])[0]
            detail = (q.get("detail") or [""])[0]
            print(f"CLIENT       {stage}" + (f" · {detail}" if detail else ""))
            self._send(204, "text/plain; charset=utf-8", b"")
        elif path == "/scene.json":
            self._send(200, "application/json; charset=utf-8", self.scene_json)
        elif path == "/scene-core.json":
            self._send(200, "application/json; charset=utf-8", self.scene_core_json)
        elif path == "/scene-bootstrap.json":
            self._send(200, "application/json; charset=utf-8", self.scene_bootstrap_json)
        elif path == "/scene-geometry.json":
            self._send(200, "application/json; charset=utf-8", self.scene_geometry_json)
        elif path == "/scene-details.json":
            self._send(200, "application/json; charset=utf-8", self.scene_details_json)
        elif path == "/db-info.json":
            self._send(200, "application/json; charset=utf-8", self.db_info_json)
        elif path == "/graph-view.json":
            self._send(200, "application/json; charset=utf-8", self.graph_view_json)
        elif path.startswith('/entity-media-status/'):
            self._serve_entity_media_status(path.split('/entity-media-status/',1)[1])
        elif path.startswith('/entity-image/'):
            self._serve_entity_asset(path.split('/entity-image/',1)[1], thumbnail=False)
        elif path.startswith('/entity-thumbnail/'):
            self._serve_entity_asset(path.split('/entity-thumbnail/',1)[1], thumbnail=True)
        elif path.startswith('/image/'):
            self._serve_asset(path.split('/image/',1)[1], thumbnail=False)
        elif path.startswith('/thumbnail/'):
            self._serve_asset(path.split('/thumbnail/',1)[1], thumbnail=True)
        elif path == "/export-db":
            self._export_db()
        elif path == "/healthz":
            self._send(200, "application/json", b'{"status":"ok"}')
        else:
            self._send(404, "text/plain; charset=utf-8", b"not found")

    def _serve_entity_media_status(self, spatial_entity_id: str):
        """Fast metadata-only WORLD→MEDIA availability check for UI hydration."""
        payload={"entity_id":spatial_entity_id,"ok":False,"approved_asset":False,"media_row":False,"thumbnail":False,"original":False}
        print(f"MEDIA STATUS START {spatial_entity_id}")
        try:
            if not self.db_path:
                payload["error"]="WORLD database path unavailable"; self._send(503,'application/json',json.dumps(payload).encode()); return
            if not self.media_db_path or not Path(self.media_db_path).exists():
                payload["error"]="MEDIA database unavailable"; self._send(503,'application/json',json.dumps(payload).encode()); return
            wc=sqlite3.connect(str(self.db_path),timeout=1.0); wc.row_factory=sqlite3.Row
            try:
                meta=wc.execute("""SELECT a.asset_id,a.media_key,a.mime_type,a.content_hash,a.byte_length,a.thumbnail_hash,a.thumbnail_byte_length
                                   FROM knowledge_entities k JOIN image_assets a ON a.entity_id=k.noun_id
                                   WHERE k.spatial_entity_id=? AND a.asset_role='HERO' AND a.is_current=1 AND a.review_status='APPROVED_REFERENCE'
                                   ORDER BY a.updated_at DESC,a.created_at DESC LIMIT 1""",(spatial_entity_id,)).fetchone()
            finally: wc.close()
            if not meta:
                payload["error"]="no current APPROVED_REFERENCE HERO in WORLD"; self._send(404,'application/json',json.dumps(payload).encode()); return
            payload.update({"approved_asset":True,"asset_id":meta['asset_id'],"media_key":meta['media_key']})
            if not meta['media_key']:
                payload["error"]="approved WORLD asset has no media_key"; self._send(409,'application/json',json.dumps(payload).encode()); return
            mc=sqlite3.connect(str(self.media_db_path),timeout=1.0); mc.row_factory=sqlite3.Row
            try:
                r=mc.execute("SELECT mime_type,thumbnail_mime_type,original_byte_length,thumbnail_byte_length FROM media_assets WHERE media_key=?",(meta['media_key'],)).fetchone()
            finally: mc.close()
            if not r:
                payload["error"]="media_key not found in MEDIA"; self._send(404,'application/json',json.dumps(payload).encode()); return
            payload.update({"media_row":True,"thumbnail":bool(r['thumbnail_byte_length']),"original":bool(r['original_byte_length']),"mime_type":r['mime_type'],"thumbnail_mime_type":r['thumbnail_mime_type'],"ok":bool(r['thumbnail_byte_length'] and r['original_byte_length'])})
            if not payload['ok']:
                payload['error']='MEDIA row exists but image bytes are absent'; self._send(409,'application/json',json.dumps(payload).encode()); return
            self._send(200,'application/json',json.dumps(payload).encode())
        except sqlite3.OperationalError as exc:
            payload['error']=f'SQLite busy/error: {exc}'; self._send(503,'application/json',json.dumps(payload).encode())
        except Exception as exc:
            payload['error']=f'{type(exc).__name__}: {exc}'; self._send(500,'application/json',json.dumps(payload).encode())
        finally:
            print(f"MEDIA STATUS END   {spatial_entity_id}")

    def _serve_entity_asset(self, spatial_entity_id: str, thumbnail: bool=False):
        """Serve the current approved HERO directly by first-class spatial entity ID."""
        if not self.db_path:
            self._send(503,'text/plain; charset=utf-8',b'WORLD database path unavailable'); return
        if not self.media_db_path or not Path(self.media_db_path).exists():
            self._send(503,'text/plain; charset=utf-8',b'MEDIA database unavailable'); return

        print(f"MEDIA ASSET  START {spatial_entity_id} · {'THUMB' if thumbnail else 'FULL'}")
        wc=sqlite3.connect(str(self.db_path),timeout=1.0); wc.row_factory=sqlite3.Row
        try:
            meta=wc.execute(
                """SELECT a.asset_id,a.media_key,a.mime_type
                   FROM knowledge_entities k
                   JOIN image_assets a ON a.entity_id=k.noun_id
                   WHERE k.spatial_entity_id=?
                     AND a.asset_role='HERO'
                     AND a.is_current=1
                     AND a.review_status='APPROVED_REFERENCE'
                   ORDER BY a.updated_at DESC,a.created_at DESC
                   LIMIT 1""",
                (spatial_entity_id,)
            ).fetchone()
        finally:
            wc.close()

        if not meta or not meta['media_key']:
            print(f"MEDIA        {spatial_entity_id} · no approved image metadata"); self._send(404,'text/plain; charset=utf-8',b'no approved image for spatial entity'); return

        mc=sqlite3.connect(str(self.media_db_path),timeout=1.0); mc.row_factory=sqlite3.Row
        try:
            r=mc.execute(
                'SELECT mime_type,original_blob,thumbnail_mime_type,thumbnail_blob FROM media_assets WHERE media_key=?',
                (meta['media_key'],)
            ).fetchone()
            if not r:
                print(f"MEDIA        {spatial_entity_id} · media_key missing from MEDIA"); self._send(404,'text/plain; charset=utf-8',b'media BLOB not found'); return
            if thumbnail and r['thumbnail_blob'] is not None:
                body=bytes(r['thumbnail_blob'])
                mime=r['thumbnail_mime_type'] or r['mime_type'] or meta['mime_type'] or 'image/jpeg'
            else:
                body=bytes(r['original_blob'])
                mime=r['mime_type'] or meta['mime_type'] or 'application/octet-stream'
            self._send(200,mime,body)
            print(f"MEDIA ASSET  END   {spatial_entity_id} · {'THUMB' if thumbnail else 'FULL'} · {len(body)} bytes")
        finally:
            mc.close()

    def _serve_asset(self, asset_id: str, thumbnail: bool=False):
        if not self.db_path:
            self._send(503,'text/plain; charset=utf-8',b'WORLD database path unavailable'); return
        if not self.media_db_path or not Path(self.media_db_path).exists():
            self._send(503,'text/plain; charset=utf-8',b'MEDIA database unavailable'); return
        wc=sqlite3.connect(str(self.db_path)); wc.row_factory=sqlite3.Row
        try:
            meta=wc.execute('SELECT media_key,mime_type FROM image_assets WHERE asset_id=?',(asset_id,)).fetchone()
        finally:
            wc.close()
        if not meta or not meta['media_key']:
            self._send(404,'text/plain; charset=utf-8',b'image asset metadata not found'); return
        mc=sqlite3.connect(str(self.media_db_path)); mc.row_factory=sqlite3.Row
        try:
            r=mc.execute('SELECT mime_type,original_blob,thumbnail_mime_type,thumbnail_blob FROM media_assets WHERE media_key=?',(meta['media_key'],)).fetchone()
            if not r:
                self._send(404,'text/plain; charset=utf-8',b'media BLOB not found'); return
            if thumbnail and r['thumbnail_blob'] is not None:
                body=bytes(r['thumbnail_blob']); mime=r['thumbnail_mime_type'] or r['mime_type'] or meta['mime_type'] or 'image/jpeg'
            else:
                body=bytes(r['original_blob']); mime=r['mime_type'] or meta['mime_type'] or 'application/octet-stream'
            self._send(200,mime,body)
        finally:
            mc.close()

    def _export_db(self):
        if not self.db_path:
            self._send(503, "text/plain; charset=utf-8", b"database path unavailable")
            return
        src = Path(self.db_path)
        if not src.exists():
            self._send(404, "text/plain; charset=utf-8", b"database not found")
            return
        stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
        tmp = Path(tempfile.gettempdir()) / f"LOOM_2226_backup_{stamp}_{os.getpid()}.sqlite3"
        try:
            _sqlite_backup(src, tmp)
            body = tmp.read_bytes()
            filename = f"LOOM_2226_backup_{stamp}.sqlite3"
            self.send_response(200)
            self.send_header("Content-Type", "application/vnd.sqlite3")
            self.send_header("Content-Disposition", f'attachment; filename="{filename}"')
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(body)
        except Exception as exc:
            self._send(500, "text/plain; charset=utf-8", f"database export failed: {exc}".encode("utf-8"))
        finally:
            try:
                tmp.unlink(missing_ok=True)
            except Exception:
                pass

    def _send(self, status: int, content_type: str, body: bytes):
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        try:
            self.wfile.write(body)
            print(f"HTTP         {self.command} {urlparse(self.path).path} -> {status} ({len(body)} bytes)")
        except (BrokenPipeError, ConnectionResetError):
            print(f"HTTP         client disconnected during {urlparse(self.path).path}")

    def log_message(self, fmt, *args):
        return


def _ensure_image_ready_atlas_contract(payload: dict) -> None:
    """Give every first-class spatial entity an Atlas image slot without creating assets."""
    atlas = payload.setdefault("atlas", {})
    for entity in payload.get("entities") or []:
        eid = entity.get("entity_id")
        if not eid:
            continue
        entry = atlas.setdefault(eid, {
            "title": entity.get("name") or eid,
            "bio": "—",
            "synth": "—",
            "status": entity.get("entity_class") or "SPATIAL ENTITY",
            "summary": "",
            "categories": {},
        })
        entry.setdefault("title", entity.get("name") or eid)
        cats = entry.setdefault("categories", {})
        overview = cats.setdefault("OVERVIEW", {})
        overview.setdefault("image_slot_status", "NO_APPROVED_IMAGE")
        prompt = entity.get("image_prompt")
        if prompt:
            overview.setdefault("image_prompt", prompt)
            overview.setdefault("image_prompt_status", "PROMPT_READY")

def _inject_inline_approved_thumbnails(payload: dict, db_info: dict | None) -> None:
    world_path = (db_info or {}).get("path")
    if not world_path or world_path == ":memory:":
        return
    wp = Path(world_path)
    media_name = DEFAULT_MEDIA_DB_FILENAME
    try:
        wc = sqlite3.connect(str(wp)); wc.row_factory = sqlite3.Row
        try:
            r = wc.execute("SELECT value FROM meta WHERE key='media_db_filename'").fetchone()
            if r and r[0]:
                media_name = str(r[0])
            rows = wc.execute(
                """SELECT k.spatial_entity_id,a.media_key
                   FROM knowledge_entities k
                   JOIN image_assets a ON a.entity_id=k.noun_id
                   WHERE k.spatial_entity_id IS NOT NULL
                     AND a.asset_role='HERO'
                     AND a.is_current=1
                     AND a.review_status='APPROVED_REFERENCE'
                     AND a.media_key IS NOT NULL"""
            ).fetchall()
        finally:
            wc.close()
    except Exception as exc:
        print("INLINE MEDIA  WORLD lookup failed:", exc)
        return

    mp = wp.with_name(media_name)
    if not mp.exists():
        print("INLINE MEDIA  MEDIA DB not found:", mp)
        return

    atlas = payload.get("atlas") or {}
    injected = 0
    mc = sqlite3.connect(str(mp)); mc.row_factory = sqlite3.Row
    try:
        for row in rows:
            eid = row["spatial_entity_id"]
            ar = atlas.get(eid)
            if not ar:
                continue
            mr = mc.execute(
                "SELECT thumbnail_mime_type,thumbnail_blob FROM media_assets WHERE media_key=?",
                (row["media_key"],)
            ).fetchone()
            if not mr or mr["thumbnail_blob"] is None:
                continue
            mime = mr["thumbnail_mime_type"] or "image/jpeg"
            b64 = base64.b64encode(bytes(mr["thumbnail_blob"])).decode("ascii")
            cats = ar.setdefault("categories", {})
            ov = cats.setdefault("OVERVIEW", {})
            ov["inline_approved_thumbnail_data_uri"] = f"data:{mime};base64,{b64}"
            ov["image_slot_status"] = "APPROVED_REFERENCE"
            injected += 1
    finally:
        mc.close()
    print(f"INLINE MEDIA  embedded approved thumbnails: {injected}")

def serve(scene: SolarScene, host: str, port: int, open_browser: bool = True, db_info: dict | None = None):
    payload = scene.to_json_dict()
    _ensure_image_ready_atlas_contract(payload)
    _inject_inline_approved_thumbnails(payload, db_info)
    SolarHandler.scene_json = (json.dumps(payload, separators=(",", ":")) + "\n").encode("utf-8")
    core_payload = dict(payload)
    core_payload["atlas"] = {}
    core_payload["catalog"] = {}
    bootstrap_payload = dict(core_payload)
    bootstrap_payload["orbit_tracks"] = []
    bootstrap_payload["local_body_orbit_tracks"] = []
    bootstrap_payload["infrastructure_orbit_tracks"] = []
    bootstrap_payload["context_layers"] = []
    geometry_payload = {"orbit_tracks": payload.get("orbit_tracks", []), "local_body_orbit_tracks": payload.get("local_body_orbit_tracks", []), "infrastructure_orbit_tracks": payload.get("infrastructure_orbit_tracks", []), "context_layers": payload.get("context_layers", [])}
    detail_payload = {"atlas": payload.get("atlas", {}), "catalog": payload.get("catalog", {})}
    SolarHandler.scene_core_json = (json.dumps(core_payload, separators=(",", ":")) + "\n").encode("utf-8")
    SolarHandler.scene_bootstrap_json = (json.dumps(bootstrap_payload, separators=(",", ":")) + "\n").encode("utf-8")
    SolarHandler.scene_geometry_json = (json.dumps(geometry_payload, separators=(",", ":")) + "\n").encode("utf-8")
    SolarHandler.scene_details_json = (json.dumps(detail_payload, separators=(",", ":")) + "\n").encode("utf-8")
    print("PAYLOAD      bootstrap", len(SolarHandler.scene_bootstrap_json), "bytes · geometry", len(SolarHandler.scene_geometry_json), "bytes · details", len(SolarHandler.scene_details_json), "bytes")
    SolarHandler.db_info_json = (json.dumps(db_info or {}, separators=(",", ":")) + "\n").encode("utf-8")
    _graph_path = (db_info or {}).get("graph_db_path")
    try:
        _graph_payload = load_graph_view_payload(_graph_path)
    except Exception as exc:
        print("GRAPH DB     load failed:", exc)
        _graph_payload = {"nodes":[],"edges":[],"available":False,"error":str(exc)}
    SolarHandler.graph_view_json = (json.dumps(_graph_payload, separators=(",", ":")) + "\n").encode("utf-8")
    if _graph_payload.get("available"):
        print("GRAPH DB    ", _graph_payload.get("path"))
        print("GRAPH ROWS  ", _graph_payload.get("node_count"), "nodes ·", _graph_payload.get("edge_count"), "typed display edges")
    SolarHandler.db_path = (db_info or {}).get("path")
    SolarHandler.media_db_path = None
    if SolarHandler.db_path and SolarHandler.db_path != ":memory:":
        world_path = Path(SolarHandler.db_path)
        media_name = DEFAULT_MEDIA_DB_FILENAME
        try:
            c=sqlite3.connect(str(world_path))
            r=c.execute("SELECT value FROM meta WHERE key='media_db_filename'").fetchone()
            if r and r[0]: media_name=str(r[0])
            c.close()
        except Exception:
            pass
        candidate=world_path.with_name(media_name)
        if candidate.exists(): SolarHandler.media_db_path=str(candidate)
    SolarHandler.client_js = CLIENT_JS.encode("utf-8")
    print("CLIENT JS    ", len(SolarHandler.client_js), "bytes · external /app.js")
    server = ThreadingHTTPServer((host, port), SolarHandler)
    url = f"http://127.0.0.1:{port}/"
    print("=" * 76)
    print("LOOM SOLAR GIS · v0.12.9 RC8 · DRAGGABLE GRAPH NODES")
    print("SCENE       ", scene.epoch_utc, scene.reference_plane, scene.reference_frame)
    print("ENTITIES    ", len(scene.entities), "(celestial bodies + 127 propagated infrastructure objects)")
    print("ORBITS      ", len(scene.orbit_tracks), "osculating ellipses")
    print("BELT        ", len(scene.context_layers[0].display_points), "context dots (non-catalog)")
    print("SOURCE      ", scene.source)
    if db_info:
        print("DATABASE    ", db_info.get("path"))
        print("MEDIA DB    ", SolarHandler.media_db_path or "not found")
        print("DB ROWS     ", "entities", db_info.get("entities"), "states", db_info.get("states"), "atlas", db_info.get("atlas_profiles"), "nodes", db_info.get("infrastructure_nodes"), "orgs", db_info.get("organizations"))
    print("URL         ", url)
    print("STOP        Ctrl+C in Pydroid")
    print("=" * 76)
    if open_browser:
        threading.Timer(0.8, lambda: webbrowser.open(url)).start()
    try:
        server.serve_forever(poll_interval=0.2)
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()


def main(argv: Iterable[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="LOOM Solar GIS v0.12.3 RC1 / Atlas exposure")
    ap.add_argument("--epoch", default=DEFAULT_EPOCH, help="UTC ISO epoch, default %(default)s")
    ap.add_argument("--port", type=int, default=8766)
    ap.add_argument("--host", default="127.0.0.1")
    ap.add_argument("--no-browser", action="store_true")
    ap.add_argument("--demo", action="store_true", help="TEST ONLY: deterministic fixture geometry; no Horizons")
    ap.add_argument("--scene-out", type=Path, help="write validated scene JSON and exit")
    ap.add_argument("--db", type=Path, help="SQLite path; defaults to Documents/LOOM/data/LOOM_2226.sqlite3 on Android")
    ap.add_argument("--civ-db", type=Path, help="locked CIVSTATE SQLite path; defaults beside --db")
    ap.add_argument("--graph-db", type=Path, help="deprecated compatibility option; if supplied it must equal --civ-db because graph views now live in production CIVSTATE")
    ap.add_argument("--refresh", action="store_true", help="ignore cached state for this epoch and refetch Horizons")
    ap.add_argument("--db-info", action="store_true", help="print SQLite contents and exit")
    ap.add_argument("--sync-image-jobs", action="store_true", help="queue image jobs for current prompts using TEST/dry-run provider")
    ap.add_argument("--dry-run-images", type=int, metavar="N", help="process up to N pending TEST image jobs into deterministic fixture BLOBs and exit")
    args = ap.parse_args(argv)

    epoch = parse_epoch(args.epoch)
    db_target: str | Path = ":memory:" if args.demo and args.db is None else (args.db or default_db_path())
    civ_target = args.civ_db or default_civstate_path(db_target)
    if args.graph_db is not None:
        explicit_graph = Path(args.graph_db).expanduser().resolve()
        resolved_civ = Path(civ_target).expanduser().resolve()
        if explicit_graph != resolved_civ:
            raise RuntimeError("--graph-db is deprecated for production; graph views must live in the selected CIVSTATE database.")
    graph_target = Path(civ_target).expanduser().resolve()
    if not graph_db_has_views(graph_target):
        raise RuntimeError(
            "Production CIVSTATE does not contain graph views. Run "
            "LOOM_2226_CIVSTATE_Graph_Views_Push_and_Full_DB_Audit_v1.0.py first."
        )
    print("GRAPH SOURCE  CIVSTATE ·", graph_target)
    civstate = CivStateStore(civ_target)
    store = SolarStore(db_target, civstate=civstate)
    try:
        store.initialize()
        if not store.preloaded_spatial_schema:
            store.seed_reference_data()
        if args.sync_image_jobs or args.dry_run_images is not None:
            q=store.sync_image_jobs()
            print("IMAGE JOBS QUEUED",q)
        if args.dry_run_images is not None:
            n=store.run_dry_image_jobs(max(0,args.dry_run_images))
            print("DRY-RUN IMAGES",n)
            print(json.dumps(store.info(),indent=2))
            return 0
        if args.db_info:
            print(json.dumps(store.info(), indent=2))
            return 0

        provider = demo_provider if args.demo else fetch_vector
        print(f"Building solar scene for {utc_iso(epoch)} ...")
        if args.demo:
            print("WARNING: DEMO MODE — TEST GEOMETRY ONLY, NOT ASTRONOMICAL AUTHORITY")
        scene = build_scene(epoch, provider=provider, store=store, refresh=(args.refresh or args.demo))
        if args.demo:
            scene = SolarScene(
                schema=scene.schema, app_version=scene.app_version, epoch_utc=scene.epoch_utc,
                reference_frame=scene.reference_frame, reference_plane=scene.reference_plane,
                physical_units=scene.physical_units, display_projection=scene.display_projection,
                max_reference_radius_au=scene.max_reference_radius_au,
                source="DEMO_TEST_FIXTURE + SQLITE + DERIVED_ORBITS",
                authority="NON_AUTHORITATIVE_TEST_ONLY",
                renderer_rule=scene.renderer_rule, orbit_semantics=scene.orbit_semantics,
                entities=scene.entities, orbit_tracks=scene.orbit_tracks,
                local_body_orbit_tracks=scene.local_body_orbit_tracks,
                infrastructure_orbit_tracks=scene.infrastructure_orbit_tracks,
                context_layers=scene.context_layers, atlas=scene.atlas, catalog=scene.catalog,
            )
        if args.scene_out:
            args.scene_out.write_text(json.dumps(scene.to_json_dict(), indent=2) + "\n", encoding="utf-8")
            print("WROTE       ", args.scene_out)
            print("DATABASE    ", store.info()["path"])
            return 0
        info = store.info()
        info["civstate"] = civstate.info()
        info["cache_hits"] = store.cache_hits
        info["cache_misses"] = store.cache_misses
        info["graph_db_path"] = str(graph_target) if graph_target else None
        serve(scene, args.host, args.port, open_browser=not args.no_browser, db_info=info)
        return 0
    finally:
        store.close()
        civstate.close()


if __name__ == "__main__":
    raise SystemExit(main())
